﻿#pragma once

/**
 * @file MyPaintDlg.h
 * @brief 주 대화 상자 클래스 선언
 */

/**
 * @brief 주 대화 상자 (과제 템플릿). 화면 구성과 동작은 지원자가 설계합니다.
 */
class CMyPaintDlg : public CDialog
{
public:
    /**
     * @brief 생성자
     * @param pParent 부모 창 (없으면 nullptr)
     */
    explicit CMyPaintDlg(CWnd* pParent = nullptr);

#ifdef AFX_DESIGN_TIME
    enum { IDD = IDD_MYPAINT_DIALOG };
#endif

protected:
    /**
     * @brief 컨트롤과 멤버 변수 사이의 데이터 교환
     * @param pDX 데이터 교환 개체
     */
    void DoDataExchange(CDataExchange* pDX) override;

    /**
     * @brief 대화 상자 초기화
     * @return 포커스를 컨트롤에 직접 지정하지 않으면 TRUE
     */
    BOOL OnInitDialog() override;

    DECLARE_MESSAGE_MAP()

private:
    HICON m_hIcon = nullptr; ///< 창 아이콘
};
﻿/**
 * @file MyPaintDlg.cpp
 * @brief 주 대화 상자 클래스 구현
 */
#include "pch.h"
#include "MyPaint.h"
#include "MyPaintDlg.h"

#ifdef _DEBUG
#define new DEBUG_NEW
#endif

BEGIN_MESSAGE_MAP(CMyPaintDlg, CDialog)
END_MESSAGE_MAP()

CMyPaintDlg::CMyPaintDlg(CWnd* pParent) : CDialog(IDD_MYPAINT_DIALOG, pParent)
{
    m_hIcon = AfxGetApp()->LoadIcon(IDR_MAINFRAME);
}

void CMyPaintDlg::DoDataExchange(CDataExchange* pDX)
{
    CDialog::DoDataExchange(pDX);
}

BOOL CMyPaintDlg::OnInitDialog()
{
    CDialog::OnInitDialog();

    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
    SetIcon(m_hIcon, FALSE); // 작은 아이콘

    return TRUE;
}
