 *
 * 개수나 메모리 한도를 넘으면 가장 오래된 기록부터 버립니다.
 */
class History
{
public:
    /** @brief 새 기록을 추가합니다. 다시 실행 기록은 버립니다. */
    void Push(HistoryEntry&& entry);

    bool CanUndo() const { return m_position > 0; }
    bool CanRedo() const { return m_position < m_entries.size(); }

