/**
 * @file Surface.h
 * @brief 픽셀에 직접 접근할 수 있는 32bpp 비트맵
 */

#include <cstdint>
#include <vector>

/** @brief 픽셀 값. 메모리 순서 B, G, R, X (정수로는 0x00RRGGBB) */
using Pixel = uint32_t;

/** @brief COLORREF → Pixel */
inline Pixel ToPixel(COLORREF color)
{
    return (static_cast<Pixel>(GetRValue(color)) << 16) | (static_cast<Pixel>(GetGValue(color)) << 8) |
           static_cast<Pixel>(GetBValue(color));
}

/** @brief Pixel → COLORREF */
inline COLORREF ToColorRef(Pixel pixel)
{
    return RGB((pixel >> 16) & 0xFF, (pixel >> 8) & 0xFF, pixel & 0xFF);
}

/**
 * @brief 사각 영역의 픽셀 사본 (실행 취소용 백업 등)
 */
struct PixelBlock
{
    CRect rect;                ///< 원본 표면에서의 위치
    std::vector<Pixel> pixels; ///< rect.Width() * rect.Height() 개, 위에서 아래로

    bool IsEmpty() const { return rect.IsRectEmpty() != FALSE; }
    size_t Bytes() const { return pixels.size() * sizeof(Pixel); }
};

/**
 * @brief 32bpp top-down DIB Section과 이를 선택한 메모리 DC
 *
 * GDI로 그릴 때는 DC()를, 픽셀을 직접 다룰 때는 Bits()를 씁니다.
 * Bits()와 블록 함수는 GdiFlush()를 먼저 호출하므로 GDI 결과와 섞어 써도 안전합니다.
 */
class Surface
{
public:
    Surface() = default;
    ~Surface();

    Surface(const Surface&) = delete;
    Surface& operator=(const Surface&) = delete;
    Surface(Surface&& other) noexcept;
    Surface& operator=(Surface&& other) noexcept;

    /**
     * @brief 표면을 만들고 한 색으로 채웁니다. 기존 내용은 사라집니다.
     * @return 성공 여부 (크기가 0 이하이거나 너무 크면 실패)
     */
    bool Create(int width, int height, COLORREF fill);

    /** @brief 자원 해제 */
    void Destroy();

    bool IsValid() const { return m_bitmap != nullptr; }
    int Width() const { return m_width; }
    int Height() const { return m_height; }
    CSize Size() const { return CSize(m_width, m_height); }
    CRect Bounds() const { return CRect(0, 0, m_width, m_height); }

    /** @brief 이 표면이 선택된 메모리 DC */
    HDC DC() const { return m_dc; }

    /** @brief 픽셀 배열 (행 간격 = Width()) */
    Pixel* Bits();
    const Pixel* Bits() const;

    /** @brief 영역 밖이면 0을 돌려줍니다. */
    Pixel GetPixel(int x, int y) const;

    /** @brief 표면 전체를 한 색으로 채웁니다. */
    void Fill(COLORREF color);

    /** @brief rect(표면 범위로 잘림)의 픽셀을 복사해 돌려줍니다. */
    PixelBlock ReadBlock(const CRect& rect) const;

    /** @brief ReadBlock으로 얻은 블록을 같은 위치에 되씁니다. */
    void WriteBlock(const PixelBlock& block);

    /** @brief 같은 크기의 다른 표면에서 rect 영역을 복사해 옵니다. */
    void CopyFrom(const Surface& source, const CRect& rect);

private:
    HDC m_dc = nullptr;
    HBITMAP m_bitmap = nullptr;
    HGDIOBJ m_oldBitmap = nullptr;
    Pixel* m_bits = nullptr;
    int m_width = 0;
    int m_height = 0;
};

/**
 * @file Surface.cpp
 * @brief Surface 구현
 */
#include "pch.h"
#include "Core/Surface.h"

#include <algorithm>
#include <utility>

namespace
{
/** @brief 한 표면에 허용하는 최대 픽셀 수 (약 400MB) */
constexpr long long kMaxPixels = 100LL * 1000 * 1000;
} // namespace

Surface::~Surface()
{
    Destroy();
}

Surface::Surface(Surface&& other) noexcept
{
    *this = std::move(other);
}

Surface& Surface::operator=(Surface&& other) noexcept
{
    if (this != &other)
    {
        Destroy();
        std::swap(m_dc, other.m_dc);
        std::swap(m_bitmap, other.m_bitmap);
        std::swap(m_oldBitmap, other.m_oldBitmap);
        std::swap(m_bits, other.m_bits);
        std::swap(m_width, other.m_width);
        std::swap(m_height, other.m_height);
    }
    return *this;
}

bool Surface::Create(int width, int height, COLORREF fill)
{
    Destroy();
    if (width <= 0 || height <= 0 || static_cast<long long>(width) * height > kMaxPixels)
    {
        return false;
    }

    BITMAPINFO bmi{};
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = width;
    bmi.bmiHeader.biHeight = -height; // 음수 = top-down
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;

    void* bits = nullptr;
    HBITMAP bitmap = ::CreateDIBSection(nullptr, &bmi, DIB_RGB_COLORS, &bits, nullptr, 0);
    if (bitmap == nullptr)
    {
        return false;
    }
    HDC dc = ::CreateCompatibleDC(nullptr);
    if (dc == nullptr)
    {
        ::DeleteObject(bitmap);
        return false;
    }

    m_dc = dc;
    m_bitmap = bitmap;
    m_oldBitmap = ::SelectObject(dc, bitmap);
    m_bits = static_cast<Pixel*>(bits);
    m_width = width;
    m_height = height;
    Fill(fill);
    return true;
}

void Surface::Destroy()
{
    if (m_dc != nullptr)
    {
        ::SelectObject(m_dc, m_oldBitmap);
        ::DeleteDC(m_dc);
    }
    if (m_bitmap != nullptr)
    {
        ::DeleteObject(m_bitmap);
    }
    m_dc = nullptr;
    m_bitmap = nullptr;
    m_oldBitmap = nullptr;
    m_bits = nullptr;
    m_width = 0;
    m_height = 0;
}

Pixel* Surface::Bits()
{
    ::GdiFlush();
    return m_bits;
}

const Pixel* Surface::Bits() const
{
    ::GdiFlush();
    return m_bits;
}

Pixel Surface::GetPixel(int x, int y) const
{
    if (x < 0 || y < 0 || x >= m_width || y >= m_height)
    {
        return 0;
    }
    return Bits()[static_cast<size_t>(y) * m_width + x];
}

void Surface::Fill(COLORREF color)
{
    if (!IsValid())
    {
        return;
    }
    Pixel* bits = Bits();
    std::fill(bits, bits + static_cast<size_t>(m_width) * m_height, ToPixel(color));
}

PixelBlock Surface::ReadBlock(const CRect& rect) const
{
    PixelBlock block;
    if (!block.rect.IntersectRect(rect, Bounds()))
    {
        block.rect.SetRectEmpty();
        return block;
    }

    const int w = block.rect.Width();
    const int h = block.rect.Height();
    block.pixels.resize(static_cast<size_t>(w) * h);
    const Pixel* src = Bits();
    for (int y = 0; y < h; ++y)
    {
        const Pixel* row = src + static_cast<size_t>(block.rect.top + y) * m_width + block.rect.left;
        std::copy(row, row + w, block.pixels.begin() + static_cast<ptrdiff_t>(y) * w);
    }
    return block;
}

void Surface::WriteBlock(const PixelBlock& block)
{
    if (block.IsEmpty())
    {
        return;
    }
    const CRect& r = block.rect;
    ASSERT(r.left >= 0 && r.top >= 0 && r.right <= m_width && r.bottom <= m_height);
    ASSERT(block.pixels.size() == static_cast<size_t>(r.Width()) * r.Height());

    const int w = r.Width();
    Pixel* dst = Bits();
    for (int y = 0; y < r.Height(); ++y)
    {
        const auto first = block.pixels.begin() + static_cast<ptrdiff_t>(y) * w;
        std::copy(first, first + w, dst + static_cast<size_t>(r.top + y) * m_width + r.left);
    }
}

void Surface::CopyFrom(const Surface& source, const CRect& rect)
{
    ASSERT(source.Size() == Size());
    CRect r;
    if (!r.IntersectRect(rect, Bounds()))
    {
        return;
    }

    const int w = r.Width();
    const Pixel* src = source.Bits();
    Pixel* dst = Bits();
    for (int y = r.top; y < r.bottom; ++y)
    {
        const size_t offset = static_cast<size_t>(y) * m_width + r.left;
        std::copy(src + offset, src + offset + w, dst + offset);
    }
}

