/**
 * @file History.h
 * @brief 실행 취소/다시 실행 기록
 */

#include <cstdint>
#include <memory>
#include <vector>

#include "Core/Command.h"
#include "Core/Surface.h"

/**
 * @brief 기록 한 칸: 실행한 명령과, 실행 직전 영향 영역의 픽셀
 */
struct HistoryEntry
{
    uint64_t id = 0;                  ///< 기록마다 고유한 번호 (저장 시점 비교용)
    std::unique_ptr<Command> command; ///< 다시 실행할 때 쓰는 명령
    PixelBlock before;                ///< 실행 취소할 때 되돌릴 픽셀

    size_t Bytes() const { return before.Bytes(); }
};

/**
 * @brief 선형 기록. 앞쪽 [0, position)이 적용된 상태, 뒤쪽은 다시 실행 가능한 기록입니다.
 *
 * 개수나 메모리 한도를 넘으면 가장 오래된 기록부터 버립니다.
 */
class History
{
public:
    /** @brief 새 기록을 추가합니다. 다시 실행 기록은 버립니다. */
    void Push(HistoryEntry&& entry);

    bool CanUndo() const { return m_position > 0; }
    bool CanRedo() const { return m_position < m_entries.size(); }

    /** @brief 위치를 한 칸 뒤로 옮기고, 되돌릴 기록을 돌려줍니다. CanUndo()일 때만 호출하세요. */
    const HistoryEntry& StepBack();

    /** @brief 위치를 한 칸 앞으로 옮기고, 다시 적용할 기록을 돌려줍니다. CanRedo()일 때만 호출하세요. */
    const HistoryEntry& StepForward();

    /** @brief 현재 상태를 만든 마지막 기록의 id (없으면 0) */
    uint64_t CurrentId() const { return m_position > 0 ? m_entries[m_position - 1].id : 0; }

    /** @brief 모두 지웁니다. */
    void Clear();

private:
    void TrimToLimits();

    std::vector<HistoryEntry> m_entries;
    size_t m_position = 0;
    size_t m_totalBytes = 0;
};

/**
 * @file History.cpp
 * @brief History 구현
 */
#include "pch.h"
#include "Core/History.h"

namespace
{
constexpr size_t kMaxEntries = 100;
constexpr size_t kMaxBytes = 512u * 1024 * 1024;
} // namespace

void History::Push(HistoryEntry&& entry)
{
    for (size_t i = m_position; i < m_entries.size(); ++i)
    {
        m_totalBytes -= m_entries[i].Bytes();
    }
    m_entries.erase(m_entries.begin() + static_cast<ptrdiff_t>(m_position), m_entries.end());

    m_totalBytes += entry.Bytes();
    m_entries.push_back(std::move(entry));
    m_position = m_entries.size();
    TrimToLimits();
}

const HistoryEntry& History::StepBack()
{
    ASSERT(CanUndo());
    return m_entries[--m_position];
}

const HistoryEntry& History::StepForward()
{
    ASSERT(CanRedo());
    return m_entries[m_position++];
}

void History::Clear()
{
    m_entries.clear();
    m_position = 0;
    m_totalBytes = 0;
}

void History::TrimToLimits()
{
    // 방금 넣은 기록 하나는 한도를 넘어도 남겨 둡니다.
    size_t drop = 0;
    size_t bytes = m_totalBytes;
    while (m_entries.size() - drop > 1 && (m_entries.size() - drop > kMaxEntries || bytes > kMaxBytes))
    {
        bytes -= m_entries[drop].Bytes();
        ++drop;
    }
    if (drop > 0)
    {
        m_entries.erase(m_entries.begin(), m_entries.begin() + static_cast<ptrdiff_t>(drop));
        m_position -= drop;
        m_totalBytes = bytes;
    }
}

#pragma once

/**
 * @file Document.h
 * @brief 그림 문서. 픽셀을 바꾸는 유일한 통로입니다.
 */

#include <memory>
#include <vector>

#include "Core/Command.h"
#include "Core/History.h"
#include "Core/Surface.h"

/**
 * @brief 문서 변경 알림을 받는 쪽 (캔버스, 메인 창, 나중에는 공유 송신부)
 */
class IDocumentListener
{
public:
    virtual ~IDocumentListener() = default;

    /** @brief 픽셀이 바뀌었습니다. dirty는 문서 좌표입니다. */
    virtual void OnDocumentChanged(const CRect& dirty) = 0;

    /** @brief 새 문서가 되었거나 캔버스 크기가 바뀌었습니다. */
    virtual void OnDocumentReset() {}

    /** @brief 새 명령이 적용되었습니다. (실행 취소/다시 실행은 포함하지 않음) */
    virtual void OnCommandApplied(const Command& /*command*/) {}
};

/**
 * @brief 그림 문서
 *
 * 모든 편집은 Apply()로 들어오고, 기록과 알림이 함께 처리됩니다.
 * 표면은 읽기 전용으로만 밖에 공개합니다.
 */
class Document
{
public:
    /** @brief 한 색으로 채운 새 문서를 만듭니다. 기록은 지워집니다. */
    bool New(int width, int height, COLORREF background = RGB(255, 255, 255));

    const Surface& GetSurface() const { return m_surface; }
    CSize Size() const { return m_surface.Size(); }

    /** @brief 명령을 적용하고 기록합니다. */
    void Apply(std::unique_ptr<Command> command);

    bool CanUndo() const { return m_history.CanUndo(); }
    bool CanRedo() const { return m_history.CanRedo(); }
    bool Undo();
    bool Redo();

    /** @brief 마지막으로 저장한 뒤 바뀌었는지 */
    bool IsModified() const { return m_history.CurrentId() != m_savedId; }

    /** @brief 지금 상태를 저장된 상태로 표시합니다. */
    void MarkSaved() { m_savedId = m_history.CurrentId(); }

    void AddListener(IDocumentListener* listener);
    void RemoveListener(IDocumentListener* listener);

private:
    void NotifyChanged(const CRect& dirty);
    void NotifyReset();

    Surface m_surface;
    History m_history;
    uint64_t m_nextId = 1;
    uint64_t m_savedId = 0;
    std::vector<IDocumentListener*> m_listeners;
};

/**
 * @file Document.cpp
 * @brief Document 구현
 */
#include "pch.h"
#include "Core/Document.h"

#include <algorithm>

bool Document::New(int width, int height, COLORREF background)
{
    Surface surface;
    if (!surface.Create(width, height, background))
    {
        return false;
    }
    m_surface = std::move(surface);
    m_history.Clear();
    m_savedId = m_history.CurrentId();
    NotifyReset();
    return true;
}

void Document::Apply(std::unique_ptr<Command> command)
{
    if (!command || !m_surface.IsValid())
    {
        return;
    }

    HistoryEntry entry;
    entry.before = m_surface.ReadBlock(command->Bounds());
    if (entry.before.IsEmpty())
    {
        return; // 캔버스 밖에만 그린 명령은 기록하지 않습니다.
    }

    command->Execute(m_surface);
    const CRect dirty = entry.before.rect;
    const Command& applied = *command;

    entry.id = m_nextId++;
    entry.command = std::move(command);
    m_history.Push(std::move(entry));

    NotifyChanged(dirty);
    for (IDocumentListener* listener : m_listeners)
    {
        listener->OnCommandApplied(applied);
    }
}

bool Document::Undo()
{
    if (!m_history.CanUndo())
    {
        return false;
    }
    const HistoryEntry& entry = m_history.StepBack();
    m_surface.WriteBlock(entry.before);
    NotifyChanged(entry.before.rect);
    return true;
}

bool Document::Redo()
{
    if (!m_history.CanRedo())
    {
        return false;
    }
    const HistoryEntry& entry = m_history.StepForward();
    entry.command->Execute(m_surface);
    NotifyChanged(entry.before.rect);
    return true;
}

void Document::AddListener(IDocumentListener* listener)
{
    if (listener != nullptr && std::find(m_listeners.begin(), m_listeners.end(), listener) == m_listeners.end())
    {
        m_listeners.push_back(listener);
    }
}

void Document::RemoveListener(IDocumentListener* listener)
{
    m_listeners.erase(std::remove(m_listeners.begin(), m_listeners.end(), listener), m_listeners.end());
}

void Document::NotifyChanged(const CRect& dirty)
{
    for (IDocumentListener* listener : m_listeners)
    {
        listener->OnDocumentChanged(dirty);
    }
}

void Document::NotifyReset()
{
    for (IDocumentListener* listener : m_listeners)
    {
        listener->OnDocumentReset();
    }
}

