{
    Document& document;
    const ToolSettings& settings;
};

/**
 * @brief 그리기 도구
 *
 * 캔버스가 마우스 입력을 문서 좌표로 바꿔 넘겨 줍니다.
 * 도구는 드래그하는 동안 미리보기 명령을 보여 주고, 끝나면 명령을 만들어 Document::Apply()에 넘깁니다.
 */
