 * 도구는 드래그하는 동안 미리보기 명령을 보여 주고, 끝나면 명령을 만들어 Document::Apply()에 넘깁니다.
 */
class Tool
{
public:
    virtual ~Tool() = default;

    virtual void OnDown(ToolContext& context, CPoint point, MouseButton button) = 0;
    virtual void OnMove(ToolContext& context, CPoint point) = 0;
    virtual void OnUp(ToolContext& context, CPoint point) = 0;

    /** @brief 진행 중인 작업을 버립니다. (Esc, 마우스 캡처 상실 등) */
    virtual void Cancel() = 0;

    /** @brief 드래그 등 진행 중인 작업이 있는지 */
    virtual bool IsActive() const = 0;

    /** @brief 진행 중인 작업의 미리보기. 캔버스가 문서 사본 위에 실행해서 보여 줍니다. */
    virtual const Command* PreviewCommand() const { return nullptr; }

    /** @brief 지난번 호출 뒤 미리보기가 바뀐 영역(문서 좌표)을 돌려주고 비웁니다. */
    virtual CRect TakePreviewDirty() { return CRect(); }

    /** @brief 캔버스 위에서 보일 커서 */
    virtual HCURSOR Cursor() const { return ::LoadCursor(nullptr, IDC_CROSS); }
};

#pragma once

/**
 * @file FreehandTool.h
 * @brief 연필, 브러시, 지우개 도구
 */

#include <memory>

#include "Core/StrokeCommand.h"
#include "Tools/Tool.h"

/**
 * @brief 마우스 궤적을 StrokeCommand로 기록하는 도구
 *
 * 연필과 브러시는 누른 버튼의 색으로, 지우개는 항상 색 2로 그립니다.
 */
class FreehandTool : public Tool
{
public:
    explicit FreehandTool(StrokeStyle style) : m_style(style) {}

    void OnDown(ToolContext& context, CPoint point, MouseButton button) override;
    void OnMove(ToolContext& context, CPoint point) override;
    void OnUp(ToolContext& context, CPoint point) override;
    void Cancel() override;
    bool IsActive() const override { return m_stroke != nullptr; }
    const Command* PreviewCommand() const override { return m_stroke.get(); }
    CRect TakePreviewDirty() override;

private:
    StrokeStyle m_style;
    std::unique_ptr<StrokeCommand> m_stroke;
    CRect m_dirty;
};

/**
 * @file FreehandTool.cpp
 * @brief FreehandTool 구현
 */
#include "pch.h"
#include "Tools/FreehandTool.h"

#include "Core/Document.h"

void FreehandTool::OnDown(ToolContext& context, CPoint point, MouseButton button)
{
    const COLORREF color = m_style == StrokeStyle::Eraser ? context.settings.color2 : context.settings.ColorFor(button);
    m_stroke = std::make_unique<StrokeCommand>(m_style, color, context.settings.strokeWidth);
    m_stroke->AddPoint(point);
    m_dirty |= m_stroke->Bounds();
}

void FreehandTool::OnMove(ToolContext& /*context*/, CPoint point)
{
    if (!m_stroke)
    {
        return;
    }
    const CPoint last = m_stroke->Points().back();
    if (m_stroke->AddPoint(point))
    {
        m_dirty |= StrokeCommand::SegmentBounds(last, point, m_stroke->Width());
    }
}

void FreehandTool::OnUp(ToolContext& context, CPoint point)
{
    if (!m_stroke)
    {
        return;
    }
    OnMove(context, point);
    // 문서가 바뀐 영역을 알려 주므로 미리보기 영역을 따로 지울 필요는 없지만, 안전하게 함께 갱신합니다.
    m_dirty |= m_stroke->Bounds();
    context.document.Apply(std::move(m_stroke));
}

void FreehandTool::Cancel()
{
    if (m_stroke)
    {
        m_dirty |= m_stroke->Bounds();
        m_stroke.reset();
    }
}

CRect FreehandTool::TakePreviewDirty()
{
    const CRect dirty = m_dirty;
    m_dirty.SetRectEmpty();
    return dirty;
}

