    }
    // 위 계산은 오른쪽 끝부터 칸을 채웁니다. 첫 칸이 남는 폭을 모두 가지면 좌표 칸이 너무 넓어지므로 고정합니다.
    edges[kPartCursor] = partWidths[kPartCursor];
    edges[kPartSelection] = edges[kPartCursor] + partWidths[kPartSelection];
    edges[kPartCanvasSize] = edges[kPartSelection] + partWidths[kPartCanvasSize];
