param([string]$Exe, [string]$OutDir)
$ErrorActionPreference = 'Stop'
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @'
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Text;
public static class W {
    [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
    [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint flags);
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
    public static IntPtr LP(int x, int y) { return (IntPtr)((y << 16) | (x & 0xFFFF)); }
    public static string Title(IntPtr h) { var s = new StringBuilder(256); GetWindowText(h, s, 256); return s.ToString(); }
    public static Bitmap Shot(IntPtr h) {
        RECT r; GetWindowRect(h, out r);
        var b = new Bitmap(r.R - r.L, r.B - r.T, PixelFormat.Format32bppArgb);
        using (var g = Graphics.FromImage(b)) { var dc = g.GetHdc(); PrintWindow(h, dc, 2); g.ReleaseHdc(dc); }
        return b;
    }
    public static int Dark(Bitmap b) {
        int n = 0;
        for (int y = 0; y < b.Height; y += 1) for (int x = 0; x < b.Width; x += 1) {
            var c = b.GetPixel(x, y); if (c.R < 40 && c.G < 40 && c.B < 40) n++;
        }
        return n;
    }
}
'@

$p = Start-Process -FilePath $Exe -PassThru
$h = [IntPtr]::Zero
for ($i = 0; $i -lt 50 -and $h -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 200; $p.Refresh(); $h = $p.MainWindowHandle }
if ($h -eq [IntPtr]::Zero) { throw 'main window not found' }
Start-Sleep -Milliseconds 500
$canvas = [W]::GetDlgItem($h, 1000)
"title0=" + [W]::Title($h)
$base = [W]::Shot($h); $base.Save("$OutDir\shot0.png"); "dark0=" + [W]::Dark($base)

# 왼쪽 버튼으로 대각선 + 꺾은 선 긋기
$WM_LBUTTONDOWN = 0x201; $WM_LBUTTONUP = 0x202; $WM_MOUSEMOVE = 0x200; $WM_COMMAND = 0x111
[W]::PostMessage($canvas, $WM_MOUSEMOVE, [IntPtr]0, [W]::LP(60, 60)) | Out-Null
[W]::PostMessage($canvas, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP(60, 60)) | Out-Null
for ($k = 1; $k -le 20; $k++) { [W]::PostMessage($canvas, $WM_MOUSEMOVE, [IntPtr]1, [W]::LP(60 + $k * 12, 60 + $k * 6)) | Out-Null }
for ($k = 1; $k -le 10; $k++) { [W]::PostMessage($canvas, $WM_MOUSEMOVE, [IntPtr]1, [W]::LP(300, 180 + $k * 10)) | Out-Null }
[W]::PostMessage($canvas, $WM_LBUTTONUP, [IntPtr]0, [W]::LP(300, 280)) | Out-Null
# 점 하나 찍기
[W]::PostMessage($canvas, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP(400, 100)) | Out-Null
[W]::PostMessage($canvas, $WM_LBUTTONUP, [IntPtr]0, [W]::LP(400, 100)) | Out-Null
Start-Sleep -Milliseconds 500
"title1=" + [W]::Title($h)
$s = [W]::Shot($h); $s.Save("$OutDir\shot1.png"); "dark1=" + [W]::Dark($s)

function Cmd($id) { [W]::SendMessage($h, $WM_COMMAND, [IntPtr]$id, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 300 }

Cmd 57643  # 실행 취소 (점)
Cmd 57643  # 실행 취소 (선)
"title2=" + [W]::Title($h)
$s = [W]::Shot($h); $s.Save("$OutDir\shot2.png"); "dark2=" + [W]::Dark($s)

Cmd 57644  # 다시 실행 (선)
"title3=" + [W]::Title($h)
$s = [W]::Shot($h); $s.Save("$OutDir\shot3.png"); "dark3=" + [W]::Dark($s)

Cmd 32771; Cmd 32771  # 확대 2단계 (200%)
$s = [W]::Shot($h); $s.Save("$OutDir\shot4.png"); "dark4=" + [W]::Dark($s)
Cmd 32773  # 100%

Cmd 57643  # 저장된 상태로 되돌린 뒤 닫기: 확인 창 없이 종료되어야 함
"title5=" + [W]::Title($h)
[W]::PostMessage($h, 0x10, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null
if ($p.WaitForExit(5000)) { "exited code=" + $p.ExitCode } else { "still running -> kill"; $p.Kill() }

