    void ZoomIn(const CPoint* anchor = nullptr);
    void ZoomOut(const CPoint* anchor = nullptr);

    /**
     * @brief 확대 배율을 바꿉니다.
     * @param anchor 화면에서 고정할 클라이언트 좌표 (nullptr이면 창 가운데)
     */
