    void SetTool(Tool* tool, const ToolSettings* settings, IToolHost* host);

    void SetObserver(ICanvasObserver* observer) { m_observer = observer; }

    /** @brief 진행 중인 도구 작업을 취소합니다. */
    void CancelTool();

    double Zoom() const { return m_zoom; }
