// 마우스
// ---------------------------------------------------------------------------

void CCanvasWnd::BeginDrag(CPoint clientPoint, MouseButton button)
{
    if (m_tool == nullptr || m_document == nullptr || m_settings == nullptr)
    {
        return;
    }
    SetFocus();
    m_dragging = true;
    m_dragButton = button;
    SetCapture();

    ToolContext context{*m_document, *m_settings};
    m_tool->OnDown(context, ClientToDoc(clientPoint), button);
    InvalidatePreview();
}

void CCanvasWnd::EndDrag(CPoint clientPoint, MouseButton /*button*/)
{
    // ReleaseCapture가 OnCaptureChanged를 부르므로, 먼저 드래그 상태를 끕니다.
    m_dragging = false;
    ToolContext context{*m_document, *m_settings};
    m_tool->OnUp(context, ClientToDoc(clientPoint));
    ReleaseCapture();
    InvalidatePreview();
}

void CCanvasWnd::OnLButtonDown(UINT /*nFlags*/, CPoint point)
{
    if (!m_dragging)
    {
        BeginDrag(point, MouseButton::Left);
    }
}

