67	BOOL CMyPaintDlg::OnInitDialog()
68	{
69	    CDialog::OnInitDialog();
70	
71	    SetIcon(m_hIcon, TRUE);  // 큰 아이콘
72	    SetIcon(m_hIcon, FALSE); // 작은 아이콘
73	    m_hAccel = ::LoadAccelerators(AfxGetResourceHandle(), MAKEINTRESOURCE(IDR_ACCELERATOR));
74	
75	    m_statusBar.Create(WS_CHILD | WS_VISIBLE | CCS_BOTTOM | SBARS_SIZEGRIP, CRect(0, 0, 0, 0), this, IDC_STATUSBAR);
76	    m_canvas.Create(this, IDC_CANVAS);
77	    m_canvas.SetObserver(this);
78	
79	    m_tool = std::make_unique<FreehandTool>(StrokeStyle::Pencil);
80	    m_canvas.SetTool(m_tool.get(), &m_toolSettings);
81	
82	    m_document.AddListener(this);
83	    m_document.New(kDefaultCanvasWidth, kDefaultCanvasHeight);
84	    m_canvas.SetDocument(&m_document);
85	
86	    // 작업 영역의 80% 크기로 가운데에 띄웁니다.
87	    CRect work;
88	    ::SystemParametersInfo(SPI_GETWORKAREA, 0, &work, 0);
89	    const int width = work.Width() * 4 / 5;
90	    const int height = work.Height() * 4 / 5;
91	    MoveWindow(work.left + (work.Width() - width) / 2, work.top + (work.Height() - height) / 2, width, height);
92	    LayoutControls();
93	
94	    UpdateTitle();
95	    UpdateStatusBar();
96	
97	    m_canvas.SetFocus();
98	    return FALSE; // 포커스를 직접 지정했습니다.
