153	void CMyPaintDlg::LayoutControls()
154	{
155	    if (m_canvas.GetSafeHwnd() == nullptr || m_statusBar.GetSafeHwnd() == nullptr)
156	    {
157	        return;
158	    }
159	
160	    CRect client;
161	    GetClientRect(&client);
162	
163	    // 상태 표시줄은 WM_SIZE를 받으면 스스로 아래에 붙습니다.
164	    m_statusBar.SendMessage(WM_SIZE);
165	    CRect statusRect;
166	    m_statusBar.GetWindowRect(&statusRect);
167	
168	    // 좌표, 선택 크기, 캔버스 크기는 고정 폭이고 배율 칸이 남는 폭을 씁니다.
169	    const int partWidth = ScaleForDpi(160);
170	    int edges[kPartCount] = {partWidth, partWidth * 2, partWidth * 3, -1};
171	    m_statusBar.SetParts(kPartCount, edges);
172	
173	    CRect canvasRect = client;
174	    canvasRect.bottom -= statusRect.Height();
175	    m_canvas.MoveWindow(canvasRect);
176	}
