bool CMyPaintDlg::ConfirmDiscardChanges()
{
    // 파일 저장 기능을 넣으면 [저장] [저장 안 함] [취소] 세 가지로 바꿉니다.
    if (!m_document.IsModified())
    {
        return true;
    }
    return AfxMessageBox(L"변경 내용이 저장되지 않았습니다.\n저장하지 않고 계속할까요?", MB_YESNO | MB_ICONWARNING) ==
           IDYES;
}

