{
    WriteRect(writer, m_clearRect);
    writer.Write(static_cast<uint32_t>(m_clearColor));
    writer.Write(static_cast<int32_t>(m_dest.x));
    writer.Write(static_cast<int32_t>(m_dest.y));
    writer.Write(static_cast<int32_t>(m_size.cx));
