    Pixel* bits = surface.Bits();
    for (int y = r.top; y < r.bottom; ++y)
    {
        Pixel* row = bits + static_cast<size_t>(y) * surface.Width();
        for (int x = r.left; x < r.right; ++x)
        {
            row[x] = (row[x] ^ 0x00FFFFFF) & 0x00FFFFFF;
        }
    }
}

