172	            {ToolId::Pencil, 0, 0, L"연필"},
173	            {ToolId::Fill, 1, 0, L"채우기"},
174	            {ToolId::Eraser, 0, 1, L"지우개 (색 2로 지움)"},
175	            {ToolId::Picker, 1, 1, L"색 선택"},
176	            {ToolId::Magnifier, 2, 1, L"돋보기 (왼쪽: 확대, 오른쪽: 축소)"},
