226	            add(ItemKind::Palette, i, CRect(topLeft, CSize(swatch, swatch)), ColorTip(kPalette[i]));
227	        }
228	        for (int i = 0; i < kCustomColorCount; ++i)
229	        {
230	            const CPoint topLeft(x + i * cell, Scale(9) + 2 * cell);
231	            add(ItemKind::Custom, i, CRect(topLeft, CSize(swatch, swatch)), L"사용자 지정 색");
232	        }
233	        x += kPaletteColumns * cell + Scale(6);
234	        add(ItemKind::EditColors, 0, CRect(x, bigTop, x + Scale(52), bigBottom), L"색 편집");
235	        x += Scale(52);
236	        endGroup(L"색");
237	    }
238	    m_contentWidth = x;
239	
240	    // 툴팁은 항목 사각형마다 하나씩 다시 등록합니다.
241	    if (m_tooltip.GetSafeHwnd() != nullptr)
242	    {
243	        for (size_t i = 0; i < m_tooltipCount; ++i)
244	        {
245	            m_tooltip.DelTool(this, static_cast<UINT_PTR>(i + 1));
246	        }
247	        for (size_t i = 0; i < m_items.size(); ++i)
248	        {
249	            m_tooltip.AddTool(this, m_items[i].tip, m_items[i].rect, static_cast<UINT_PTR>(i + 1));
250	        }
251	        m_tooltipCount = m_items.size();
252	    }
