108	void CToolPanel::EnsureFonts()
109	{
110	    const UINT dpi = Dpi();
111	    if (dpi == m_fontDpi)
112	    {
113	        return;
114	    }
115	    m_fontDpi = dpi;
116	    m_textFont.DeleteObject();
117	    m_glyphFont.DeleteObject();
118	    m_bigGlyphFont.DeleteObject();
119	
120	    auto makeFont = [this](CFont& font, int pixelHeight, const wchar_t* face) {
121	        LOGFONT lf{};
122	        lf.lfHeight = -Scale(pixelHeight);
123	        lf.lfWeight = FW_NORMAL;
124	        lf.lfCharSet = DEFAULT_CHARSET;
125	        lf.lfQuality = CLEARTYPE_QUALITY;
126	        wcscpy_s(lf.lfFaceName, face);
127	        font.CreateFontIndirect(&lf);
128	    };
129	    makeFont(m_textFont, 12, L"Segoe UI");
130	    makeFont(m_glyphFont, 16, L"Segoe MDL2 Assets");
131	    makeFont(m_bigGlyphFont, 26, L"Segoe MDL2 Assets");
132	}
