138	void CToolPanel::Layout()
139	{
140	    EnsureFonts();
141	    m_items.clear();
142	    m_groups.clear();
143	
144	    const int labelTop = Scale(76);
145	    const int labelBottom = Scale(94);
146	    const int bigTop = Scale(8);
147	    const int bigBottom = Scale(70);
148	    int x = Scale(8);
149	    int groupStart = x;
150	
151	    auto add = [this](ItemKind kind, int value, const CRect& rect, const CString& tip) {
152	        m_items.push_back({kind, value, rect, tip});
153	    };
154	    auto endGroup = [&](const wchar_t* label) {
155	        m_groups.push_back({label, CRect(groupStart, labelTop, x, labelBottom), x + Scale(8)});
156	        x += Scale(17);
157	        groupStart = x;
158	    };
159	
160	    // 도구: 2줄 x 3칸 (텍스트 도구 자리는 다음 단계에서 채웁니다)
161	    {
162	        const int cell = Scale(28);
163	        const int size = Scale(26);
164	        struct Slot
165	        {
166	            ToolId tool;
167	            int col;
168	            int row;
169	            const wchar_t* tip;
170	        };
171	        const Slot slots[] = {
172	            {ToolId::Pencil, 0, 0, L"연필"},
173	            {ToolId::Fill, 1, 0, L"채우기"},
174	            {ToolId::Eraser, 0, 1, L"지우개 (색 2로 지움)"},
175	            {ToolId::Picker, 1, 1, L"색 선택"},
176	            {ToolId::Magnifier, 2, 1, L"돋보기 (왼쪽: 확대, 오른쪽: 축소)"},
177	        };
178	        for (const Slot& s : slots)
179	        {
180	            const CPoint topLeft(x + s.col * cell, Scale(10) + s.row * Scale(32));
181	            add(ItemKind::Tool, static_cast<int>(s.tool), CRect(topLeft, CSize(size, size)), s.tip);
182	        }
183	        x += 3 * cell;
184	        endGroup(L"도구");
185	    }
186	
187	    // 브러시
188	    add(ItemKind::Tool, static_cast<int>(ToolId::Brush), CRect(x, bigTop, x + Scale(48), bigBottom), L"브러시");
189	    x += Scale(48);
190	    endGroup(L"브러시");
191	
192	    // 도형: 6열 격자 + 윤곽선/채우기
193	    {
194	        const int cell = Scale(22);
195	        constexpr int kColumns = 6;
196	        for (int i = 0; i < static_cast<int>(ShapeKind::Count); ++i)
197	        {
198	            const CPoint topLeft(x + (i % kColumns) * cell, Scale(9) + (i / kColumns) * cell);
199	            add(ItemKind::Shape, i, CRect(topLeft, CSize(cell - Scale(1), cell - Scale(1))),
200	                ShapeKindName(static_cast<ShapeKind>(i)));
201	        }
202	        x += kColumns * cell + Scale(8);
203	        add(ItemKind::Outline, 0, CRect(x, Scale(12), x + Scale(92), Scale(36)), L"도형 윤곽선");
204	        add(ItemKind::Fill, 0, CRect(x, Scale(42), x + Scale(92), Scale(66)), L"도형 채우기 (색 2)");
205	        x += Scale(92);
206	        endGroup(L"도형");
207	    }
208	
209	    // 크기
210	    add(ItemKind::Size, 0, CRect(x, bigTop, x + Scale(48), bigBottom), L"크기 (선 두께)");
211	    x += Scale(48);
212	    endGroup(L"크기");
213	
214	    // 색: 색 1, 색 2, 팔레트, 색 편집
215	    {
216	        add(ItemKind::ColorSlot, 0, CRect(x, bigTop, x + Scale(48), bigBottom), L"색 1 (왼쪽 버튼으로 그릴 때)");
217	        x += Scale(50);
218	        add(ItemKind::ColorSlot, 1, CRect(x, bigTop, x + Scale(48), bigBottom), L"색 2 (오른쪽 버튼, 지우개, 도형 채우기)");
219	        x += Scale(56);
220	
221	        const int cell = Scale(22);
222	        const int swatch = Scale(20);
223	        for (int i = 0; i < static_cast<int>(std::size(kPalette)); ++i)
224	        {
225	            const CPoint topLeft(x + (i % kPaletteColumns) * cell, Scale(9) + (i / kPaletteColumns) * cell);
226	            add(ItemKind::Palette, i, CRect(topLeft, CSize(swatch, swatch)), ColorTip(kPalette[i]));
227	        }
228	        for (int i = 0; i < kCustomColorCount; ++i)
229	        {
230	            const CPoint topLeft(x + i * cell, Scale(9) + 2 * cell);
231	            add(ItemKind::Custom, i, CRect(topLeft, CSize(swatch, swatch)), L"사용자 지정 색");
232	        }
233	        x += kPaletteColumns * cell + Scale(6);
234	        add(ItemKind::EditColors, 0, CRect(x, bigTop, x + Scale(52), bigBottom), L"색 편집");
235	        x += Scale(52);
236	        endGroup(L"색");
237	    }
238	    m_contentWidth = x;
239	
240	    // 툴팁은 항목 사각형마다 하나씩 다시 등록합니다.
241	    if (m_tooltip.GetSafeHwnd() != nullptr)
242	    {
243	        for (size_t i = 0; i < m_tooltipCount; ++i)
244	        {
245	            m_tooltip.DelTool(this, static_cast<UINT_PTR>(i + 1));
246	        }
247	        for (size_t i = 0; i < m_items.size(); ++i)
248	        {
249	            m_tooltip.AddTool(this, m_items[i].tip, m_items[i].rect, static_cast<UINT_PTR>(i + 1));
250	        }
251	        m_tooltipCount = m_items.size();
252	    }
253	}
