};

/**
 * @brief 도구 패널
 *
 * 컨트롤을 여러 개 두는 대신 한 창이 모든 버튼을 직접 그리고 클릭 위치로 판별합니다.
 * 표시할 상태는 ToolSettings와 현재 도구에서 읽고, 바꿀 때는 설정을 고친 뒤 관찰자에게 알립니다.
 */
class CToolPanel : public CWnd
{
public:
