589	void CToolPanel::Activate(const Item& item, MouseButton button)
590	{
591	    if (m_settings == nullptr || m_observer == nullptr)
592	    {
593	        return;
594	    }
595	
596	    switch (item.kind)
597	    {
598	    case ItemKind::Tool:
599	        m_observer->OnPanelToolSelected(static_cast<ToolId>(item.value));
600	        return;
601	    case ItemKind::Shape:
602	        m_settings->shapeKind = static_cast<ShapeKind>(item.value);
603	        m_observer->OnPanelToolSelected(ToolId::Shape);
604	        return;
605	    case ItemKind::Outline:
606	    case ItemKind::Fill:
607	    {
608	        bool& flag = item.kind == ItemKind::Outline ? m_settings->shapeOutline : m_settings->shapeFill;
609	        const int choice = ShowChoiceMenu(item, {L"없음", L"단색"}, flag ? 1 : 0);
610	        if (choice < 0)
611	        {
612	            return;
613	        }
614	        flag = choice == 1;
615	        break;
616	    }
617	    case ItemKind::Size:
618	    {
619	        std::vector<CString> choices;
620	        for (int i = 0; i < kSizeLevels; ++i)
621	        {
622	            CString text;
623	            text.Format(L"%dpx", ToolSettings::WidthAt(CurrentWidthKind(), i));
624	            choices.push_back(text);
625	        }
626	        const int choice = ShowChoiceMenu(item, choices, m_settings->sizeLevel);
627	        if (choice < 0)
628	        {
629	            return;
630	        }
631	        m_settings->sizeLevel = choice;
632	        break;
633	    }
634	    case ItemKind::ColorSlot:
635	        m_settings->activeColorSlot = item.value;
636	        break;
637	    case ItemKind::Palette:
638	    case ItemKind::Custom:
639	    {
640	        const COLORREF color =
641	            item.kind == ItemKind::Palette ? kPalette[item.value] : m_settings->customColors[item.value];
642	        if (color == CLR_INVALID)
643	        {
644	            return; // 비어 있는 사용자 지정 칸
645	        }
646	        // 오른쪽 클릭은 항상 색 2, 왼쪽 클릭은 선택된 칸에 넣습니다.
647	        if (button == MouseButton::Right || m_settings->activeColorSlot == 1)
648	        {
649	            m_settings->color2 = color;
650	        }
651	        else
652	        {
653	            m_settings->color1 = color;
654	        }
655	        break;
656	    }
657	    case ItemKind::EditColors:
658	        m_observer->OnPanelEditColors();
659	        return;
660	    }
661	
662	    Invalidate(FALSE);
663	    m_observer->OnPanelSettingsChanged();
664	}

