constexpr int kDefaultCanvasHeight = 600;

/** @brief 창 최소 높이 (96 DPI 기준). 최소 폭은 도구 패널 폭에 맞춥니다. */
constexpr int kMinWindowHeight = 480;

/** @brief 상태 표시줄 칸 */
enum StatusPart
{
    kPartCursor,
    kPartSelection,
    kPartCanvasSize,
    kPartZoom,
    kPartCount,
};

