 */
class CMyPaintDlg : public CDialog,
                    public IDocumentListener,
                    public ICanvasObserver,
                    public IToolHost,
                    public IToolPanelObserver
{
public:
    /**
     * @brief 생성자
     * @param pParent 부모 창 (없으면 nullptr)
