    {
        return;
    }
    ApplyCommand(std::make_unique<ResizeSkewCommand>(dialog.NewSize(), dialog.SkewHorizontal(),
                                                     dialog.SkewVertical(), m_toolSettings.color2));
}

void CMyPaintDlg::OnImageProperties()
