$g.Dispose(); $bmp.Save($testPng, [System.Drawing.Imaging.ImageFormat]::Png); $bmp.Dispose()

function Start-App($arg) {
  $script:p = if ($arg) { Start-Process -FilePath $Exe -ArgumentList "`"$arg`"" -PassThru } else { Start-Process -FilePath $Exe -PassThru }
  $script:h = [IntPtr]::Zero
  for ($i = 0; $i -lt 50 -and $script:h -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 200; $script:p.Refresh(); $script:h = $script:p.MainWindowHandle }
  Start-Sleep -Milliseconds 600
  $script:canvas = [W]::GetDlgItem($script:h, 1000); $script:panel = [W]::GetDlgItem($script:h, 1002)
}
function Cmd($id) { [W]::PostMessage($h, $WM_COMMAND, [IntPtr]$id, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 300 }
function PanelClick([int]$x, [int]$y) {
  [W]::PostMessage($panel, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP($x, $y)) | Out-Null
  [W]::PostMessage($panel, $WM_LBUTTONUP, [IntPtr]0, [W]::LP($x, $y)) | Out-Null
  Start-Sleep -Milliseconds 200
}
function Drag([int]$x0, [int]$y0, [int]$x1, [int]$y1) {
  [W]::PostMessage($canvas, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP($x0 + 5, $y0 + 5)) | Out-Null
  for ($k = 1; $k -le 8; $k++) {
    [W]::PostMessage($canvas, $WM_MOUSEMOVE, [IntPtr]1, [W]::LP([int]($x0 + ($x1 - $x0) * $k / 8) + 5, [int]($y0 + ($y1 - $y0) * $k / 8) + 5)) | Out-Null
  }
  [W]::PostMessage($canvas, $WM_LBUTTONUP, [IntPtr]0, [W]::LP($x1 + 5, $y1 + 5)) | Out-Null
  Start-Sleep -Milliseconds 250
}
function Click([int]$x, [int]$y) { Drag $x $y $x $y }
function Type([string]$text) { foreach ($c in $text.ToCharArray()) { [W]::PostMessage($canvas, $WM_CHAR, [IntPtr][int]$c, [IntPtr]1) | Out-Null }; Start-Sleep -Milliseconds 300 }
function Esc { [W]::PostMessage($canvas, 0x100, [IntPtr]0x1B, [IntPtr]0) | Out-Null; Start-Sleep -Milliseconds 250 }
function Shot($name) { $b = [W]::Shot($h); $b.Save("$OutDir\$name.png"); $b.Dispose() }
# 캔버스 창 기준 문서 좌표의 색 (100% 배율, 스크롤 0)
function DocPixel([int]$x, [int]$y) { $b = [W]::Shot($canvas); $c = $b.GetPixel($x + 5, $y + 5); $b.Dispose(); "{0},{1},{2}" -f $c.R, $c.G, $c.B }
# 캔버스 창 안 흰/그림 영역 크기 (배경색이 아닌 연속 영역의 오른쪽/아래 끝)
function CanvasExtent() {
  $b = [W]::Shot($canvas); $bg = $b.GetPixel($b.Width - 30, $b.Height - 30)
  $w = 0; for ($x = 5; $x -lt $b.Width - 20; $x++) { if ($b.GetPixel($x, 6) -ne $bg) { $w = $x - 4 } }
  $hh = 0; for ($y = 5; $y -lt $b.Height - 20; $y++) { if ($b.GetPixel(6, $y) -ne $bg) { $hh = $y - 4 } }
  $b.Dispose(); "$w x $hh"
}

