﻿#pragma once

/**
 * @file ShapeCommand.h
 * @brief 선, 사각형, 타원, 다각형 같은 도형을 그리는 명령
 */

#include "Core/Command.h"

/** @brief 도형 종류. 직렬화에 쓰이므로 순서를 바꾸지 말고 끝에만 추가하세요. */
enum class ShapeKind : uint8_t
{
    Line,
    Ellipse,
    Rectangle,
    RoundRect,
    Triangle,
    RightTriangle,
    Diamond,
    Pentagon,
    Hexagon,
    ArrowRight,
    ArrowLeft,
    ArrowUp,
    ArrowDown,
    Star4,
    Star5,
    Star6,
    Heart,
    Count,
};

/** @brief 도구 패널 툴팁 등에 쓰는 이름 */
const wchar_t* ShapeKindName(ShapeKind kind);

/** @brief 도형의 윤곽선과 채우기 */
struct ShapeStyle
{
    bool outline = true;                     ///< 윤곽선 그리기
    bool fill = false;                       ///< 안쪽 채우기
    COLORREF outlineColor = RGB(0, 0, 0);    ///< 윤곽선 색 (선 도형은 항상 이 색)
    COLORREF fillColor = RGB(255, 255, 255); ///< 채우기 색
    int width = 1;                           ///< 윤곽선 두께
};

/**
 * @brief 시작점과 끝점으로 정해지는 상자 안에 도형을 그립니다.
 *
 * 명령 실행과 도구 패널 아이콘이 같은 함수를 써서 모양이 일치합니다.
 */
void DrawShape(HDC dc, ShapeKind kind, CPoint start, CPoint end, const ShapeStyle& style);

/**
 * @brief Shift를 누르고 그릴 때의 끝점 보정
 *
 * 선은 45° 단위로, 나머지 도형은 정사각형 상자로 맞춥니다.
 */
CPoint ConstrainShapeEnd(ShapeKind kind, CPoint start, CPoint end);

/**
 * @brief 도형 명령
 */
class ShapeCommand : public Command
{
public:
    ShapeCommand(ShapeKind kind, CPoint start, CPoint end, const ShapeStyle& style)
        : m_kind(kind), m_start(start), m_end(end), m_style(style)
    {
    }

    CommandType Type() const override { return CommandType::Shape; }
    CRect Bounds() const override;
    void Execute(Surface& surface) const override;
    void Write(ByteWriter& writer) const override;

    static std::unique_ptr<ShapeCommand> Read(ByteReader& reader);

private:
    ShapeKind m_kind;
    CPoint m_start;
    CPoint m_end;
    ShapeStyle m_style;
};
﻿#pragma once

/**
 * @file ShapeTool.h
 * @brief 도형 도구
 */

#include <memory>

#include "Core/ShapeCommand.h"
#include "Tools/Tool.h"

/**
 * @brief 드래그한 상자에 현재 선택된 도형을 그립니다.
 *
 * 왼쪽 버튼은 윤곽선 = 색 1, 채우기 = 색 2이고 오른쪽 버튼은 반대입니다.
 * Shift를 누르면 선은 45° 단위, 다른 도형은 정사각형 비율로 고정됩니다.
 */
class ShapeTool : public Tool
{
public:
    void OnDown(ToolContext& context, CPoint point, MouseButton button) override;
    void OnMove(ToolContext& context, CPoint point) override;
    void OnUp(ToolContext& context, CPoint point) override;
    void Cancel() override;
    bool IsActive() const override { return m_preview != nullptr; }
    const Command* PreviewCommand() const override { return m_preview.get(); }
    CRect TakePreviewDirty() override;

private:
    void UpdatePreview(ToolContext& context, CPoint point);

    CPoint m_start;
    MouseButton m_button = MouseButton::Left;
    ShapeKind m_kind = ShapeKind::Rectangle;
    ShapeStyle m_style;
    std::unique_ptr<ShapeCommand> m_preview;
    CRect m_dirty;
};
﻿/**
 * @file ShapeTool.cpp
 * @brief ShapeTool 구현
 */
#include "pch.h"
#include "Tools/ShapeTool.h"

#include "Core/Document.h"

void ShapeTool::OnDown(ToolContext& context, CPoint point, MouseButton button)
{
    // 드래그하는 동안 패널 설정이 바뀌어도 시작할 때의 모양을 유지합니다.
    const ToolSettings& s = context.settings;
    m_start = point;
    m_button = button;
    m_kind = s.shapeKind;
    m_style.outline = s.shapeOutline;
    m_style.fill = s.shapeFill;
    m_style.outlineColor = s.ColorFor(button);
    m_style.fillColor = s.OtherColor(button);
    m_style.width = s.WidthFor(WidthKind::Brush);
    UpdatePreview(context, point);
}

void ShapeTool::OnMove(ToolContext& context, CPoint point)
{
    if (m_preview)
    {
        UpdatePreview(context, point);
    }
}

void ShapeTool::OnUp(ToolContext& context, CPoint point)
{
    if (!m_preview)
    {
        return;
    }
    UpdatePreview(context, point);
    context.document.Apply(std::move(m_preview));
}

void ShapeTool::Cancel()
{
    if (m_preview)
    {
        m_dirty |= m_preview->Bounds();
        m_preview.reset();
    }
}

void ShapeTool::UpdatePreview(ToolContext& context, CPoint point)
{
    const CPoint end = context.shift ? ConstrainShapeEnd(m_kind, m_start, point) : point;
    if (m_preview)
    {
        m_dirty |= m_preview->Bounds(); // 이전 모양을 지우기 위해
    }
    m_preview = std::make_unique<ShapeCommand>(m_kind, m_start, end, m_style);
    m_dirty |= m_preview->Bounds();
}

CRect ShapeTool::TakePreviewDirty()
{
    const CRect dirty = m_dirty;
    m_dirty.SetRectEmpty();
    return dirty;
}
﻿#pragma once

/**
 * @file CanvasWnd.h
 * @brief 문서를 보여 주고 마우스 입력을 도구로 넘기는 캔버스 창
 */

#include "Core/Document.h"
#include "Core/Surface.h"
#include "Tools/Tool.h"

/**
 * @brief 캔버스 상태 변화를 받는 쪽 (상태 표시줄 갱신용)
 */
class ICanvasObserver
{
public:
    virtual ~ICanvasObserver() = default;

    /** @brief 마우스가 움직였습니다. inside가 false면 이미지 밖입니다. */
    virtual void OnCanvasCursor(bool inside, CPoint docPoint) = 0;

    /** @brief 확대 배율이 바뀌었습니다. */
    virtual void OnCanvasZoomChanged(double zoom) = 0;
};

/**
 * @brief 캔버스 창
 *
 * - 문서 위에 도구 미리보기를 합성한 사본(m_composite)을 확대/축소해 그립니다.
 * - 확대/축소, 스크롤 같은 보기 상태는 여기에만 있고 문서에는 없습니다.
 */
class CCanvasWnd : public CWnd, public IDocumentListener
{
public:
    CCanvasWnd() = default;
    ~CCanvasWnd() override;

    /** @brief 자식 창으로 만듭니다. */
    BOOL Create(CWnd* parent, UINT id);

    /** @brief 보여 줄 문서를 연결합니다. */
    void SetDocument(Document* document);

    /** @brief 현재 도구, 설정, 도구가 부를 호스트를 연결합니다. 이전 도구의 작업은 확정됩니다. */
    void SetTool(Tool* tool, const ToolSettings* settings, IToolHost* host);

    void SetObserver(ICanvasObserver* observer) { m_observer = observer; }

    /** @brief 진행 중인 드래그를 취소합니다. */
    void CancelTool();

    /** @brief 드래그를 취소하고, 남아 있는 작업(선택 영역, 텍스트)을 문서에 확정합니다. */
    void CommitTool();

    /** @brief Esc: 드래그 중이면 취소, 아니면 남은 작업을 확정합니다. */
    void HandleEscape();

    /** @brief 도구 설정이 바뀌었음을 도구에 알리고 미리보기를 다시 그립니다. */
    void NotifySettingsChanged();

    /** @brief 도구 상태가 밖에서 바뀌었을 때(선택 영역 붙여넣기 등) 미리보기를 다시 그립니다. */
    void InvalidateToolPreview() { InvalidatePreview(); }

    /** @brief 화면에 보이는 영역의 왼쪽 위 문서 좌표 (0 이상) */
    CPoint VisibleDocOrigin() const;

    double Zoom() const { return m_zoom; }
    /** @brief 한 단계 확대/축소합니다. anchor는 SetZoom과 같습니다. */
    void ZoomIn(const CPoint* anchor = nullptr);
    void ZoomOut(const CPoint* anchor = nullptr);

    /**
     * @brief 확대 배율을 바꿉니다.
     * @param anchor 화면에서 고정할 클라이언트 좌표 (nullptr이면 창 가운데)
     */
    void SetZoom(double zoom, const CPoint* anchor = nullptr);

    /** @brief 문서 좌표 docPoint가 화면에서 제자리에 있도록 한 단계 확대/축소합니다. */
    void ZoomAtDoc(CPoint docPoint, bool zoomIn);

    // IDocumentListener
    void OnDocumentChanged(const CRect& dirty) override;
    void OnDocumentReset() override;

protected:
    afx_msg void OnPaint();
    afx_msg BOOL OnEraseBkgnd(CDC* pDC);
    afx_msg void OnSize(UINT nType, int cx, int cy);
    afx_msg void OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg void OnVScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg BOOL OnMouseWheel(UINT nFlags, short zDelta, CPoint pt);
    afx_msg void OnLButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnLButtonUp(UINT nFlags, CPoint point);
    afx_msg void OnRButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnRButtonUp(UINT nFlags, CPoint point);
