 */
class ICanvasObserver
{
public:
    virtual ~ICanvasObserver() = default;

    /** @brief 마우스가 움직였습니다. inside가 false면 이미지 밖입니다. */
    virtual void OnCanvasCursor(bool inside, CPoint docPoint) = 0;

