243	void CCanvasWnd::OnPaint()
244	{
245	    CPaintDC dc(this);
246	    const CRect clip(dc.m_ps.rcPaint);
247	    if (clip.IsRectEmpty())
248	    {
249	        return;
250	    }
251	
252	    // 더블 버퍼: 무효 영역 크기만큼만 메모리 비트맵을 만듭니다.
253	    CDC mem;
254	    mem.CreateCompatibleDC(&dc);
255	    CBitmap buffer;
256	    buffer.CreateCompatibleBitmap(&dc, clip.Width(), clip.Height());
257	    CBitmap* oldBitmap = mem.SelectObject(&buffer);
258	    mem.SetViewportOrg(-clip.left, -clip.top);
259	    mem.FillSolidRect(clip, kBackground);
260	
261	    if (m_document != nullptr && m_composite.IsValid())
262	    {
263	        const CRect docBounds(CPoint(0, 0), m_document->Size());
264	        CRect visible;
265	        if (visible.IntersectRect(DocToClient(docBounds), clip))
266	        {
267	            CRect docRect(ClientToDoc(visible.TopLeft()), ClientToDoc(visible.BottomRight() - CPoint(1, 1)) + CPoint(1, 1));
268	            docRect &= docBounds;
269	            UpdateComposite(docRect);
270	
271	            const CRect dest = DocToClient(docRect);
272	            if (m_zoom < 1.0)
273	            {
274	                mem.SetStretchBltMode(HALFTONE);
275	                ::SetBrushOrgEx(mem.GetSafeHdc(), 0, 0, nullptr);
276	            }
277	            else
278	            {
279	                mem.SetStretchBltMode(COLORONCOLOR);
280	            }
281	            ::StretchBlt(mem.GetSafeHdc(), dest.left, dest.top, dest.Width(), dest.Height(), m_composite.DC(),
282	                         docRect.left, docRect.top, docRect.Width(), docRect.Height(), SRCCOPY);
283	        }
284	    }
285	
286	    DrawOverlay(mem);
287	
288	    dc.BitBlt(clip.left, clip.top, clip.Width(), clip.Height(), &mem, clip.left, clip.top, SRCCOPY);
289	    mem.SelectObject(oldBitmap);
290	}
