292	void CCanvasWnd::UpdateComposite(const CRect& docRect)
293	{
294	    m_composite.CopyFrom(m_document->GetSurface(), docRect);
295	
296	    if (m_tool == nullptr)
297	    {
298	        return;
299	    }
300	    // 확정될 때와 같은 코드로 그려서 미리보기와 결과가 픽셀 단위로 같게 합니다.
301	    // (선택 영역/텍스트처럼 드래그가 끝난 뒤에도 남는 미리보기가 있으므로 IsActive와 관계없이 그립니다.)
302	    HDC dc = m_composite.DC();
303	    const int saved = ::SaveDC(dc);
304	    ::IntersectClipRect(dc, docRect.left, docRect.top, docRect.right, docRect.bottom);
305	    m_tool->DrawPreview(m_composite);
306	    ::RestoreDC(dc, saved);
307	}
