309	void CCanvasWnd::DrawOverlay(CDC& dc)
310	{
311	    if (m_tool == nullptr)
312	    {
313	        return;
314	    }
315	    const CRect docRect = m_tool->OverlayRect();
316	    if (docRect.IsRectEmpty())
317	    {
318	        return;
319	    }
320	    // 영역 바로 바깥에 흰 실선 + 검은 점선을 겹쳐 어떤 배경에서도 보이게 합니다.
321	    CRect r = DocToClient(docRect);
322	    r.InflateRect(1, 1);
323	    CBrush* oldBrush = static_cast<CBrush*>(dc.SelectStockObject(NULL_BRUSH));
324	    CPen white(PS_SOLID, 1, RGB(255, 255, 255));
325	    CPen dotted(PS_DOT, 1, RGB(0, 0, 0));
326	    CPen* oldPen = dc.SelectObject(&white);
327	    dc.Rectangle(r);
328	    dc.SelectObject(&dotted);
329	    const int oldMode = dc.SetBkMode(TRANSPARENT);
330	    dc.Rectangle(r);
331	    dc.SetBkMode(oldMode);
332	    dc.SelectObject(oldPen);
333	    dc.SelectObject(oldBrush);
334	}
