347	void CCanvasWnd::UpdateScrollBars()
348	{
349	    if (GetSafeHwnd() == nullptr)
350	    {
351	        return;
352	    }
353	    CRect client;
354	    GetClientRect(&client);
355	    const CSize content = ContentSize();
356	    m_scroll.x = std::clamp(m_scroll.x, 0L, (std::max)(0L, content.cx - client.Width()));
357	    m_scroll.y = std::clamp(m_scroll.y, 0L, (std::max)(0L, content.cy - client.Height()));
358	
359	    SCROLLINFO si{};
360	    si.cbSize = sizeof(si);
361	    si.fMask = SIF_RANGE | SIF_PAGE | SIF_POS | SIF_DISABLENOSCROLL;
362	    si.nMin = 0;
363	
364	    si.nMax = content.cx - 1;
365	    si.nPage = static_cast<UINT>(client.Width());
366	    si.nPos = m_scroll.x;
367	    SetScrollInfo(SB_HORZ, &si, TRUE);
368	
369	    si.nMax = content.cy - 1;
370	    si.nPage = static_cast<UINT>(client.Height());
371	    si.nPos = m_scroll.y;
372	    SetScrollInfo(SB_VERT, &si, TRUE);
373	}
