378	    GetClientRect(&client);
379	    const CSize content = ContentSize();
380	    position.x = std::clamp(position.x, 0L, (std::max)(0L, content.cx - client.Width()));
381	    position.y = std::clamp(position.y, 0L, (std::max)(0L, content.cy - client.Height()));
382	    if (position == m_scroll)
383	    {
384	        return;
385	    }
386	    m_scroll = position;
387	    SetScrollPos(SB_HORZ, m_scroll.x);
388	    SetScrollPos(SB_VERT, m_scroll.y);
389	    Invalidate(FALSE);
390	}
391	
392	void CCanvasWnd::HandleScroll(int bar, UINT code)
393	{
394	    SCROLLINFO si{};
395	    si.cbSize = sizeof(si);
396	    GetScrollInfo(bar, &si, SIF_ALL);
397	
398	    int pos = si.nPos;
399	    switch (code)
400	    {
401	    case SB_LINEUP:
402	        pos -= kLineScroll;
403	        break;
404	    case SB_LINEDOWN:
405	        pos += kLineScroll;
406	        break;
407	    case SB_PAGEUP:
408	        pos -= static_cast<int>(si.nPage);
409	        break;
410	    case SB_PAGEDOWN:
411	        pos += static_cast<int>(si.nPage);
412	        break;
413	    case SB_THUMBTRACK:
414	    case SB_THUMBPOSITION:
415	        pos = si.nTrackPos;
416	        break;
417	    case SB_TOP:
418	        pos = 0;
419	        break;
420	    case SB_BOTTOM:
421	        pos = si.nMax;
422	        break;
423	    default:
424	        return;
425	    }
426	
427	    CPoint next = m_scroll;
428	    (bar == SB_HORZ ? next.x : next.y) = pos;
429	    ScrollTo(next);
430	}
431	
432	void CCanvasWnd::OnHScroll(UINT nSBCode, UINT /*nPos*/, CScrollBar* /*pScrollBar*/)
433	{
434	    HandleScroll(SB_HORZ, nSBCode);
435	}
