442	BOOL CCanvasWnd::OnMouseWheel(UINT nFlags, short zDelta, CPoint pt)
443	{
444	    if ((nFlags & MK_CONTROL) != 0)
445	    {
446	        // Ctrl + 휠: 마우스 위치를 기준으로 확대/축소
447	        ScreenToClient(&pt);
448	        if (zDelta > 0)
449	        {
450	            ZoomIn(&pt);
451	        }
452	        else if (zDelta < 0)
453	        {
454	            ZoomOut(&pt);
455	        }
456	        return TRUE;
457	    }
458	
459	    const int amount = -zDelta * kLineScroll * 3 / WHEEL_DELTA;
460	    if ((nFlags & MK_SHIFT) != 0)
461	    {
462	        ScrollTo(m_scroll + CPoint(amount, 0));
463	    }
464	    else
465	    {
466	        ScrollTo(m_scroll + CPoint(0, amount));
467	    }
468	    return TRUE;
469	}
470	
471	void CCanvasWnd::ZoomIn(const CPoint* anchor)
472	{
473	    for (double z : kZoomLevels)
474	    {
475	        if (z > m_zoom + kZoomEpsilon)
476	        {
477	            SetZoom(z, anchor);
478	            return;
479	        }
480	    }
481	}
482	
483	void CCanvasWnd::ZoomOut(const CPoint* anchor)
484	{
485	    for (auto it = std::rbegin(kZoomLevels); it != std::rend(kZoomLevels); ++it)
486	    {
487	        if (*it < m_zoom - kZoomEpsilon)
488	        {
489	            SetZoom(*it, anchor);
490	            return;
491	        }
492	    }
493	}
494	
495	void CCanvasWnd::SetZoom(double zoom, const CPoint* anchor)
496	{
497	    zoom = std::clamp(zoom, kZoomLevels[0], kZoomLevels[std::size(kZoomLevels) - 1]);
498	    if (std::abs(zoom - m_zoom) < kZoomEpsilon)
499	    {
500	        return;
501	    }
502	
503	    CRect client;
504	    GetClientRect(&client);
505	    const CPoint a = anchor != nullptr ? *anchor : client.CenterPoint();
506	
507	    // 기준점 아래에 있던 문서 위치가 확대 후에도 같은 자리에 오도록 스크롤을 맞춥니다.
508	    const double docX = (a.x + m_scroll.x - kMargin) / m_zoom;
509	    const double docY = (a.y + m_scroll.y - kMargin) / m_zoom;
510	    m_zoom = zoom;
511	    m_scroll.x = static_cast<int>(std::lround(docX * m_zoom + kMargin - a.x));
512	    m_scroll.y = static_cast<int>(std::lround(docY * m_zoom + kMargin - a.y));
513	
514	    UpdateScrollBars();
515	    Invalidate(FALSE);
516	    if (m_observer != nullptr)
517	    {
518	        m_observer->OnCanvasZoomChanged(m_zoom);
519	    }
520	}
521	
522	void CCanvasWnd::ZoomAtDoc(CPoint docPoint, bool zoomIn)
523	{
524	    // 픽셀의 가운데를 기준으로 삼아 확대 후에도 같은 픽셀이 마우스 아래에 오게 합니다.
525	    const CPoint anchor(DocToClientX(docPoint.x + 0.5), DocToClientY(docPoint.y + 0.5));
526	    if (zoomIn)
527	    {
528	        ZoomIn(&anchor);
529	    }
530	    else
531	    {
532	        ZoomOut(&anchor);
533	    }
534	}
