673	LRESULT CCanvasWnd::OnImeStartComposition(WPARAM /*wParam*/, LPARAM /*lParam*/)
674	{
675	    if (m_tool != nullptr && m_tool->WantsTextInput())
676	    {
677	        return 0; // 조합 중인 글자는 텍스트 상자 안에 직접 그리므로 IME 기본 창을 띄우지 않습니다.
678	    }
679	    return Default();
680	}
681	
682	LRESULT CCanvasWnd::OnImeComposition(WPARAM /*wParam*/, LPARAM lParam)
683	{
684	    if (m_tool == nullptr || !m_tool->WantsTextInput() || m_document == nullptr)
685	    {
686	        return Default();
687	    }
688	
689	    HIMC imc = ::ImmGetContext(m_hWnd);
690	    if (imc == nullptr)
691	    {
692	        return Default();
693	    }
694	    auto readString = [imc](DWORD index) {
695	        const LONG bytes = ::ImmGetCompositionStringW(imc, index, nullptr, 0);
696	        std::wstring text(bytes > 0 ? static_cast<size_t>(bytes) / sizeof(wchar_t) : 0, L'\0');
697	        if (bytes > 0)
698	        {
699	            ::ImmGetCompositionStringW(imc, index, text.data(), static_cast<DWORD>(bytes));
700	        }
701	        return text;
702	    };
703	
704	    ToolContext context = MakeContext(false);
705	    // 완성된 글자를 먼저 넣고, 이어서 조합 중인 글자를 갱신합니다. (한 메시지에 둘 다 올 수 있음)
706	    if ((lParam & GCS_RESULTSTR) != 0)
707	    {
708	        for (const wchar_t ch : readString(GCS_RESULTSTR))
709	        {
710	            m_tool->OnChar(context, ch);
711	        }
712	        m_tool->OnComposition(context, std::wstring());
713	    }
714	    if ((lParam & GCS_COMPSTR) != 0)
715	    {
716	        m_tool->OnComposition(context, readString(GCS_COMPSTR));
717	    }
718	    ::ImmReleaseContext(m_hWnd, imc);
719	    InvalidatePreview();
720	    return 0; // 기본 처리를 하지 않으므로 WM_CHAR가 중복으로 오지 않습니다.
721	}
722	
723	LRESULT CCanvasWnd::OnImeEndComposition(WPARAM /*wParam*/, LPARAM /*lParam*/)
724	{
725	    if (m_tool != nullptr && m_tool->WantsTextInput() && m_document != nullptr)
726	    {
727	        ToolContext context = MakeContext(false);
728	        m_tool->OnComposition(context, std::wstring());
729	        InvalidatePreview();
730	        return 0;
731	    }
732	    return Default();
733	}
