753	BOOL CCanvasWnd::OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message)
754	{
755	    if (nHitTest == HTCLIENT && m_tool != nullptr)
756	    {
757	        CPoint point;
758	        ::GetCursorPos(&point);
759	        ScreenToClient(&point);
760	        ::SetCursor(m_tool->CursorAt(ClientToDoc(point)));
761	        return TRUE;
762	    }
763	    return CWnd::OnSetCursor(pWnd, nHitTest, message);
764	}
765	
766	void CCanvasWnd::ReportCursor(CPoint clientPoint)
767	{
768	    if (m_observer == nullptr || m_document == nullptr)
769	    {
770	        return;
771	    }
772	    const CPoint docPoint = ClientToDoc(clientPoint);
773	    const CRect docBounds(CPoint(0, 0), m_document->Size());
774	    m_observer->OnCanvasCursor(docBounds.PtInRect(docPoint) != FALSE, docPoint);
