 * 이 성질 덕분에 다시 실행, 리플레이, 원격 공유가 모두 같은 명령으로 동작합니다.
 */
class Command
{
public:
    virtual ~Command() = default;

    /** @brief 명령 종류 */
    virtual CommandType Type() const = 0;

    /** @brief 이 명령이 바꿀 수 있는 영역 (문서 좌표, 표면 범위로 자르기 전) */
