    /** @brief 표면에 명령을 적용합니다. DC에 클리핑이 걸려 있으면 그 안에만 그려도 됩니다. */
    virtual void Execute(Surface& surface) const = 0;

    /** @brief 종류 번호를 뺀 본문을 씁니다. */
    virtual void Write(ByteWriter& writer) const = 0;
