    CCanvasWnd m_canvas;
    CStatusBarCtrl m_statusBar;

    CString m_filePath; ///< 열거나 저장한 파일 경로 (새 그림이면 비어 있음)
    CString m_title;    ///< 마지막으로 설정한 창 제목 (불필요한 갱신 방지)

    /** @brief 색 편집 대화 상자(CColorDialog)의 사용자 지정 색 16칸 */
    std::array<COLORREF, 16> m_colorDialogCustom{};
};

