cat > "$TEMP/doc.py" 2>/dev/null; f=Core/Document.cpp
# Reset: add restored notify
perl -0pi -e 's/(    m_savedId = m_history.CurrentId\(\);\n    NotifyReset\(\);\n)/$1    NotifyRestored(m_surface.Bounds(), true);\n/' $f
# Undo size-changing branch
perl -0pi -e 's/(        m_surface = std::move\(restored\);\n        NotifyReset\(\);\n)/$1        NotifyRestored(m_surface.Bounds(), true);\n/' $f
# Undo normal
perl -0pi -e 's/(    m_surface.WriteBlock\(entry.before\);\n    NotifyChanged\(entry.before.rect\);\n)/$1    NotifyRestored(entry.before.rect, false);\n/' $f
# Redo
perl -0pi -e 's/(    if \(entry.command->ChangesSize\(\)\)\n    \{\n        NotifyReset\(\);\n    \}\n    else\n    \{\n        NotifyChanged\(entry.before.rect\);\n    \}\n)(    return true;\n\}\n\nvoid Document::AddListener)/$1    NotifyRestored(entry.command->ChangesSize() ? m_surface.Bounds() : entry.before.rect, entry.command->ChangesSize());\n$2/' $f
cat >> $f <<'EOF'

void Document::NotifyRestored(const CRect& dirty, bool whole)
{
    for (IDocumentListener* listener : m_listeners)
    {
        listener->OnDocumentRestored(dirty, whole);
    }
}

void Document::ApplyUnrecorded(const Command& command)
{
    if (!m_surface.IsValid())
    {
        return;
    }
    CRect dirty = command.ComputeBounds(m_surface);
    command.Execute(m_surface);
    if (command.ChangesSize())
    {
        NotifyReset();
        return;
    }
    dirty &= m_surface.Bounds();
    if (!dirty.IsRectEmpty())
    {
        NotifyChanged(dirty);
    }
}
EOF
