bool ParseDiscoveryReply(const uint8_t* data, size_t size, RoomInfo& info);

/** @brief 이 PC의 IPv4 주소들 (공유 시작 대화 상자에 보여 줄 용도) */
std::vector<std::wstring> LocalAddresses();
} // namespace Share

