406	bool CToolPanel::IsSelected(const Item& item) const
407	{
408	    switch (item.kind)
409	    {
410	    case ItemKind::Tool:
411	        return static_cast<int>(m_currentTool) == item.value;
412	    case ItemKind::Shape:
413	        return m_currentTool == ToolId::Shape && m_settings != nullptr &&
414	               static_cast<int>(m_settings->shapeKind) == item.value;
415	    case ItemKind::ColorSlot:
416	        return m_settings != nullptr && m_settings->activeColorSlot == item.value;
417	    default:
418	        return false;
419	    }
420	}
