584	void CToolPanel::DrawFillIcon(CDC& dc, const CRect& rect)
585	{
586	    // 기울어진 통과 떨어지는 물방울
587	    const double s = (std::min)(rect.Width(), rect.Height());
588	    const double cx = rect.CenterPoint().x - s * 0.06;
589	    const double cy = rect.CenterPoint().y + s * 0.02;
590	    auto pt = [&](double dx, double dy) { return CPoint(static_cast<int>(cx + dx * s), static_cast<int>(cy + dy * s)); };
591	    const POINT bucket[] = {pt(-0.30, -0.02), pt(-0.04, -0.28), pt(0.22, -0.02), pt(-0.04, 0.24)};
592	
593	    CPen pen(PS_SOLID, (std::max)(1, Scale(1)), kText);
594	    CPen* oldPen = dc.SelectObject(&pen);
595	    CBrush* oldBrush = static_cast<CBrush*>(dc.SelectStockObject(NULL_BRUSH));
596	    dc.Polygon(bucket, static_cast<int>(std::size(bucket)));
597	    dc.MoveTo(pt(-0.17, -0.15));
598	    dc.LineTo(pt(-0.26, -0.33));
599	
600	    CBrush drop(kText);
601	    dc.SelectObject(&drop);
602	    const CPoint d = pt(0.27, 0.16);
603	    const int radius = (std::max)(2, static_cast<int>(s * 0.08));
604	    dc.Ellipse(d.x - radius, d.y - radius, d.x + radius, d.y + radius + radius / 2);
605	
606	    dc.SelectObject(oldBrush);
607	    dc.SelectObject(oldPen);
608	}
