153	void CToolPanel::EnsureFonts()
154	{
155	    const UINT dpi = Dpi();
156	    if (dpi == m_fontDpi)
157	    {
158	        return;
159	    }
160	    m_fontDpi = dpi;
161	    m_textFont.DeleteObject();
162	    m_glyphFont.DeleteObject();
163	    m_bigGlyphFont.DeleteObject();
164	
165	    auto makeFont = [this](CFont& font, int pixelHeight, const wchar_t* face) {
166	        LOGFONT lf{};
167	        lf.lfHeight = -Scale(pixelHeight);
168	        lf.lfWeight = FW_NORMAL;
169	        lf.lfCharSet = DEFAULT_CHARSET;
170	        lf.lfQuality = CLEARTYPE_QUALITY;
171	        wcscpy_s(lf.lfFaceName, face);
172	        font.CreateFontIndirect(&lf);
173	    };
174	    makeFont(m_textFont, 12, L"Segoe UI");
175	    makeFont(m_glyphFont, 16, L"Segoe MDL2 Assets");
176	    makeFont(m_bigGlyphFont, 26, L"Segoe MDL2 Assets");
177	}
