366	void CToolPanel::OnPaint()
367	{
368	    CPaintDC paintDc(this);
369	    CRect client;
370	    GetClientRect(&client);
371	    if (client.IsRectEmpty())
372	    {
373	        return;
374	    }
375	    EnsureFonts();
376	
377	    CDC dc;
378	    dc.CreateCompatibleDC(&paintDc);
379	    CBitmap buffer;
380	    buffer.CreateCompatibleBitmap(&paintDc, client.Width(), client.Height());
381	    CBitmap* oldBitmap = dc.SelectObject(&buffer);
382	
383	    dc.FillSolidRect(client, kPanelBack);
384	    dc.FillSolidRect(0, client.bottom - 1, client.Width(), 1, kPanelBorder);
385	    dc.SetBkMode(TRANSPARENT);
386	
387	    CFont* oldFont = dc.SelectObject(&m_textFont);
388	    dc.SetTextColor(kLabel);
389	    for (const Group& g : m_groups)
390	    {
391	        CRect label = g.labelRect;
392	        dc.DrawText(g.label, label, DT_CENTER | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX);
393	        dc.FillSolidRect(g.separatorX, Scale(8), 1, Scale(86), kPanelBorder);
394	    }
395	
396	    for (size_t i = 0; i < m_items.size(); ++i)
397	    {
398	        DrawItem(dc, m_items[i], static_cast<int>(i) == m_hover);
399	    }
400	    dc.SelectObject(oldFont);
