422	void CToolPanel::DrawItem(CDC& dc, const Item& item, bool hover)
423	{
424	    const bool selected = IsSelected(item);
425	    const bool isSwatch = item.kind == ItemKind::Palette || item.kind == ItemKind::Custom;
426	
427	    if (!isSwatch && (selected || hover))
428	    {
429	        CBrush fill(selected ? kSelectedFill : kHoverFill);
430	        CPen border(PS_SOLID, 1, selected ? kSelectedBorder : kHoverBorder);
431	        CBrush* oldBrush = dc.SelectObject(&fill);
432	        CPen* oldPen = dc.SelectObject(&border);
433	        dc.Rectangle(item.rect);
434	        dc.SelectObject(oldPen);
435	        dc.SelectObject(oldBrush);
436	    }
437	
438	    dc.SetTextColor(kText);
439	    CRect r = item.rect;
440	    switch (item.kind)
441	    {
442	    case ItemKind::Tool:
443	    {
444	        switch (static_cast<ToolId>(item.value))
445	        {
446	        case ToolId::Pencil: DrawGlyph(dc, r, kGlyphPencil, m_glyphFont); break;
447	        case ToolId::Fill: DrawFillIcon(dc, r); break;
448	        case ToolId::Text: DrawGlyph(dc, r, kGlyphText, m_glyphFont); break;
449	        case ToolId::Eraser: DrawGlyph(dc, r, kGlyphEraser, m_glyphFont); break;
450	        case ToolId::Picker: DrawGlyph(dc, r, kGlyphPicker, m_glyphFont); break;
451	        case ToolId::Magnifier: DrawGlyph(dc, r, kGlyphMagnifier, m_glyphFont); break;
452	        case ToolId::Brush: DrawGlyph(dc, r, kGlyphBrush, m_bigGlyphFont); break;
453	        case ToolId::Select: DrawBigButton(dc, r, kGlyphSelect, item.label); break;
454	        default: break;
455	        }
456	        break;
457	    }
458	    case ItemKind::Command:
459	        if (item.value == ID_EDIT_PASTE)
460	        {
461	            DrawBigButton(dc, r, GlyphForCommand(ID_EDIT_PASTE), item.label);
462	        }
463	        else
464	        {
465	            DrawSmallButton(dc, r, GlyphForCommand(static_cast<UINT>(item.value)), item.label);
466	        }
467	        break;
468	    case ItemKind::RotateMenu:
469	        DrawSmallButton(dc, r, kGlyphRotate, item.label);
470	        break;
471	    case ItemKind::Shape:
472	    {
473	        CRect icon = r;
474	        icon.DeflateRect(Scale(3), Scale(3));
475	        ShapeStyle style;
476	        style.outlineColor = kText;
477	        DrawShape(dc.GetSafeHdc(), static_cast<ShapeKind>(item.value), icon.TopLeft(),
478	                  icon.BottomRight() - CPoint(1, 1), style);
479	        break;
480	    }
481	    case ItemKind::Outline:
482	    case ItemKind::Fill:
483	    {
484	        const bool on = m_settings != nullptr &&
485	                        (item.kind == ItemKind::Outline ? m_settings->shapeOutline : m_settings->shapeFill);
486	        CString text;
487	        text.Format(L"%s: %s  ▾", item.kind == ItemKind::Outline ? L"윤곽선" : L"채우기", on ? L"단색" : L"없음");
488	        r.DeflateRect(Scale(6), 0);
489	        dc.DrawText(text, r, DT_LEFT | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX);
490	        break;
491	    }
492	    case ItemKind::Font:
493	    {
494	        CString text;
495	        if (m_settings != nullptr)
496	        {
497	            text.Format(L"글꼴: %s, %dpt%s%s%s", m_settings->textFace.c_str(), m_settings->textPointSize,
498	                        m_settings->textBold ? L", 굵게" : L"", m_settings->textItalic ? L", 기울임" : L"",
499	                        m_settings->textUnderline ? L", 밑줄" : L"");
500	        }
501	        r.DeflateRect(Scale(6), 0);
502	        dc.DrawText(text, r, DT_LEFT | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX | DT_END_ELLIPSIS);
503	        break;
504	    }
505	    case ItemKind::TextBackground:
506	    {
507	        const bool opaque = m_settings != nullptr && m_settings->textOpaque;
508	        CString text;
509	        text.Format(L"배경: %s  ▾", opaque ? L"불투명" : L"투명");
510	        r.DeflateRect(Scale(6), 0);
511	        dc.DrawText(text, r, DT_LEFT | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX);
512	        break;
513	    }
514	    case ItemKind::Size:
515	        DrawSizeIcon(dc, r);
516	        break;
517	    case ItemKind::ColorSlot:
518	    {
519	        const int side = item.value == 0 ? Scale(30) : Scale(22);
520	        const CPoint center(r.CenterPoint().x, r.top + Scale(22));
521	        const CRect swatch(center.x - side / 2, center.y - side / 2, center.x - side / 2 + side,
522	                           center.y - side / 2 + side);
523	        DrawSwatch(dc, swatch, m_settings == nullptr ? RGB(0, 0, 0)
524	                                                     : (item.value == 0 ? m_settings->color1 : m_settings->color2));
525	        CRect label(r.left, r.bottom - Scale(22), r.right, r.bottom - Scale(4));
526	        dc.DrawText(item.value == 0 ? L"색 1" : L"색 2", label, DT_CENTER | DT_SINGLELINE | DT_VCENTER);
527	        break;
528	    }
529	    case ItemKind::Palette:
530	        DrawSwatch(dc, r, kPalette[item.value]);
531	        if (hover)
532	        {
533	            dc.Draw3dRect(r, kSelectedBorder, kSelectedBorder);
534	        }
535	        break;
536	    case ItemKind::Custom:
537	    {
538	        const COLORREF color = m_settings != nullptr ? m_settings->customColors[item.value] : CLR_INVALID;
539	        if (color == CLR_INVALID)
540	        {
541	            dc.FillSolidRect(r, kEmptySwatch);
542	            dc.Draw3dRect(r, kPanelBorder, kPanelBorder);
543	        }
544	        else
545	        {
546	            DrawSwatch(dc, r, color);
547	        }
548	        if (hover)
549	        {
550	            dc.Draw3dRect(r, kSelectedBorder, kSelectedBorder);
551	        }
552	        break;
553	    }
554	    case ItemKind::EditColors:
555	        DrawBigButton(dc, r, kGlyphPalette, item.label);
556	        break;
557	    }
558	}
