560	void CToolPanel::DrawGlyph(CDC& dc, const CRect& rect, const wchar_t* glyph, CFont& font)
561	{
562	    CFont* oldFont = dc.SelectObject(&font);
563	    CRect r = rect;
564	    dc.DrawText(glyph, 1, r, DT_CENTER | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX);
565	    dc.SelectObject(oldFont);
566	}
