568	void CToolPanel::DrawBigButton(CDC& dc, const CRect& rect, const wchar_t* glyph, const CString& label)
569	{
570	    CRect icon(rect.left, rect.top + Scale(4), rect.right, rect.top + Scale(38));
571	    DrawGlyph(dc, icon, glyph, m_bigGlyphFont);
572	    CRect text(rect.left, rect.bottom - Scale(26), rect.right, rect.bottom - Scale(4));
573	    dc.DrawText(label, text, DT_CENTER | DT_SINGLELINE | DT_VCENTER | DT_NOPREFIX);
574	}
