635	int CToolPanel::HitTest(CPoint point) const
636	{
637	    for (size_t i = 0; i < m_items.size(); ++i)
638	    {
639	        if (m_items[i].rect.PtInRect(point))
640	        {
641	            return static_cast<int>(i);
642	        }
643	    }
644	    return -1;
