647	void CToolPanel::OnMouseMove(UINT nFlags, CPoint point)
648	{
649	    if (!m_trackingLeave)
650	    {
651	        TRACKMOUSEEVENT tme{};
652	        tme.cbSize = sizeof(tme);
653	        tme.dwFlags = TME_LEAVE;
654	        tme.hwndTrack = GetSafeHwnd();
655	        m_trackingLeave = ::TrackMouseEvent(&tme) != FALSE;
656	    }
657	    const int hover = HitTest(point);
658	    if (hover != m_hover)
659	    {
660	        m_hover = hover;
661	        Invalidate(FALSE);
662	    }
663	    CWnd::OnMouseMove(nFlags, point);
664	}
665	
666	void CToolPanel::OnMouseLeave()
667	{
668	    m_trackingLeave = false;
669	    if (m_hover != -1)
670	    {
671	        m_hover = -1;
672	        Invalidate(FALSE);
673	    }
674	}
675	
676	void CToolPanel::OnLButtonDown(UINT /*nFlags*/, CPoint point)
677	{
678	    const int hit = HitTest(point);
679	    if (hit >= 0)
680	    {
681	        // 항목 처리 중에 다시 배치될 수 있으므로(텍스트 도구 전환) 복사해 둡니다.
682	        const Item item = m_items[static_cast<size_t>(hit)];
683	        Activate(item, MouseButton::Left);
684	    }
685	}
686	
687	void CToolPanel::OnRButtonDown(UINT /*nFlags*/, CPoint point)
688	{
689	    const int hit = HitTest(point);
690	    if (hit >= 0)
691	    {
692	        const Item item = m_items[static_cast<size_t>(hit)];
693	        Activate(item, MouseButton::Right);
694	    }
695	}
696	
697	WidthKind CToolPanel::CurrentWidthKind() const
698	{
699	    switch (m_currentTool)
700	    {
701	    case ToolId::Pencil: return WidthKind::Pencil;
702	    case ToolId::Eraser: return WidthKind::Eraser;
703	    default: return WidthKind::Brush;
704	    }
705	}
706	
707	int CToolPanel::ShowChoiceMenu(const Item& item, const std::vector<CString>& choices, int checked)
708	{
709	    CMenu menu;
710	    menu.CreatePopupMenu();
711	    for (size_t i = 0; i < choices.size(); ++i)
712	    {
713	        menu.AppendMenu(MF_STRING | (static_cast<int>(i) == checked ? MF_CHECKED : 0), i + 1, choices[i]);
714	    }
715	    CPoint at(item.rect.left, item.rect.bottom);
716	    ClientToScreen(&at);
717	    const UINT chosen = menu.TrackPopupMenu(TPM_LEFTALIGN | TPM_TOPALIGN | TPM_RETURNCMD | TPM_NONOTIFY, at.x, at.y,
718	                                            this);
719	    return static_cast<int>(chosen) - 1;
720	}
721	
722	void CToolPanel::Activate(const Item& item, MouseButton button)
723	{
724	    if (m_settings == nullptr || m_observer == nullptr)
725	    {
726	        return;
727	    }
728	
729	    switch (item.kind)
730	    {
731	    case ItemKind::Tool:
732	        m_observer->OnPanelToolSelected(static_cast<ToolId>(item.value));
733	        return;
734	    case ItemKind::Shape:
735	        m_settings->shapeKind = static_cast<ShapeKind>(item.value);
736	        m_observer->OnPanelToolSelected(ToolId::Shape);
737	        return;
738	    case ItemKind::Command:
739	        m_observer->OnPanelCommand(static_cast<UINT>(item.value));
740	        return;
741	    case ItemKind::RotateMenu:
742	    {
743	        std::vector<CString> choices;
744	        for (const RotateChoice& c : kRotateChoices)
745	        {
746	            choices.push_back(c.label);
747	        }
748	        const int choice = ShowChoiceMenu(item, choices, -1);
749	        if (choice >= 0)
750	        {
751	            m_observer->OnPanelCommand(kRotateChoices[choice].command);
752	        }
753	        return;
754	    }
755	    case ItemKind::Font:
756	        m_observer->OnPanelEditFont();
757	        return;
758	    case ItemKind::TextBackground:
759	    {
760	        const int choice = ShowChoiceMenu(item, {L"투명", L"불투명"}, m_settings->textOpaque ? 1 : 0);
761	        if (choice < 0)
762	        {
763	            return;
764	        }
765	        m_settings->textOpaque = choice == 1;
766	        break;
767	    }
768	    case ItemKind::Outline:
769	    case ItemKind::Fill:
770	    {
771	        bool& flag = item.kind == ItemKind::Outline ? m_settings->shapeOutline : m_settings->shapeFill;
772	        const int choice = ShowChoiceMenu(item, {L"없음", L"단색"}, flag ? 1 : 0);
773	        if (choice < 0)
774	        {
775	            return;
776	        }
777	        flag = choice == 1;
778	        break;
779	    }
780	    case ItemKind::Size:
781	    {
782	        std::vector<CString> choices;
783	        for (int i = 0; i < kSizeLevels; ++i)
784	        {
785	            CString text;
786	            text.Format(L"%dpx", ToolSettings::WidthAt(CurrentWidthKind(), i));
787	            choices.push_back(text);
788	        }
789	        const int choice = ShowChoiceMenu(item, choices, m_settings->sizeLevel);
790	        if (choice < 0)
791	        {
792	            return;
793	        }
794	        m_settings->sizeLevel = choice;
795	        break;
796	    }
797	    case ItemKind::ColorSlot:
798	        m_settings->activeColorSlot = item.value;
799	        break;
800	    case ItemKind::Palette:
801	    case ItemKind::Custom:
802	    {
803	        const COLORREF color =
804	            item.kind == ItemKind::Palette ? kPalette[item.value] : m_settings->customColors[item.value];
805	        if (color == CLR_INVALID)
806	        {
807	            return; // 비어 있는 사용자 지정 칸
808	        }
809	        // 오른쪽 클릭은 항상 색 2, 왼쪽 클릭은 선택된 칸에 넣습니다.
810	        if (button == MouseButton::Right || m_settings->activeColorSlot == 1)
811	        {
812	            m_settings->color2 = color;
813	        }
814	        else
815	        {
816	            m_settings->color1 = color;
817	        }
818	        break;
819	    }
820	    case ItemKind::EditColors:
821	        m_observer->OnPanelEditColors();
822	        return;
823	    }
824	
825	    Invalidate(FALSE);
826	    m_observer->OnPanelSettingsChanged();
827	}
