    m_shareName = myName; // 이름이 겹치면 방장이 "준호 (2)"처럼 바꿔 줍니다.
    m_sharePanel.SetInputEnabled(true);
    CString notice;
    notice.Format(L"'%s' 방에 들어왔습니다. (%s 님의 그림)", room.c_str(), host.c_str());
