'@
$WM_LBUTTONDOWN = 0x201; $WM_LBUTTONUP = 0x202; $WM_MOUSEMOVE = 0x200; $WM_COMMAND = 0x111; $WM_SETTEXT = 0x000C
$ID_SHARE_START = 32783; $ID_SHARE_JOIN = 32784; $ID_SHARE_STOP = 32785; $ID_UNDO = 0xE12B; $ID_ROTATE_RIGHT = 32777
$M = 12

function Start-App() {
  $p = Start-Process -FilePath $Exe -PassThru
  $h = [IntPtr]::Zero
  for ($i = 0; $i -lt 50 -and $h -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 200; $p.Refresh(); $h = $p.MainWindowHandle }
  Start-Sleep -Milliseconds 500
  [pscustomobject]@{ P = $p; H = $h; Canvas = [W]::GetDlgItem($h, 1000); Panel = [W]::GetDlgItem($h, 1002); Share = [W]::GetDlgItem($h, 1003) }
}
function Cmd($app, $id) { [W]::PostMessage($app.H, $WM_COMMAND, [IntPtr]$id, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 300 }
function Wait-Dialog($app, $title) {
  for ($i = 0; $i -lt 40; $i++) { $d = [W]::FindDialog($app.P.Id, $app.H, $title); if ($d -ne [IntPtr]::Zero) { return $d }; Start-Sleep -Milliseconds 100 }
  return [IntPtr]::Zero
}
function PanelClick($app, [int]$x, [int]$y) {
  [W]::PostMessage($app.Panel, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP($x, $y)) | Out-Null
  [W]::PostMessage($app.Panel, $WM_LBUTTONUP, [IntPtr]0, [W]::LP($x, $y)) | Out-Null
  Start-Sleep -Milliseconds 200
}
function Down($app, [int]$x, [int]$y) { [W]::PostMessage($app.Canvas, $WM_LBUTTONDOWN, [IntPtr]1, [W]::LP($x + $M, $y + $M)) | Out-Null }
function Move($app, [int]$x, [int]$y) { [W]::PostMessage($app.Canvas, $WM_MOUSEMOVE, [IntPtr]1, [W]::LP($x + $M, $y + $M)) | Out-Null }
function Up($app, [int]$x, [int]$y) { [W]::PostMessage($app.Canvas, $WM_LBUTTONUP, [IntPtr]0, [W]::LP($x + $M, $y + $M)) | Out-Null }
function Drag($app, [int]$x0, [int]$y0, [int]$x1, [int]$y1) {
  Down $app $x0 $y0
  for ($k = 1; $k -le 8; $k++) { Move $app ([int]($x0 + ($x1 - $x0) * $k / 8)) ([int]($y0 + ($y1 - $y0) * $k / 8)) }
  Up $app $x1 $y1
  Start-Sleep -Milliseconds 300
}
function DocPixel($app, [int]$x, [int]$y) { $b = [W]::Shot($app.Canvas); $c = $b.GetPixel($x + $M, $y + $M); $b.Dispose(); "{0},{1},{2}" -f $c.R, $c.G, $c.B }
function CanvasExtent($app) {
  $b = [W]::Shot($app.Canvas); $bg = $b.GetPixel(2, 2)
  $w = 0; for ($x = $M; $x -lt $b.Width - 20; $x++) { if ($b.GetPixel($x, $M + 2) -ne $bg) { $w = $x - $M + 1 } }
  $hh = 0; for ($y = $M; $y -lt $b.Height - 20; $y++) { if ($b.GetPixel($M + 2, $y) -ne $bg) { $hh = $y - $M + 1 } }
  $b.Dispose(); "$w x $hh"
}
function Shot($app, $name) { $b = [W]::Shot($app.H); $b.Save("$OutDir\$name.png"); $b.Dispose() }
function ChatLog($app) { [W]::Text([W]::GetDlgItem($app.Share, 1031)) }
function Participants($app) {
  $lb = [W]::GetDlgItem($app.Share, 1030)
  $n = [int][W]::SendMessage($lb, 0x018B, [IntPtr]::Zero, [IntPtr]::Zero)
