[W]::PostMessage([W]::GetDlgItem($B.Share, 1033), 0x00F5, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null  # BM_CLICK
Start-Sleep -Milliseconds 500
[W]::SendMessage([W]::GetDlgItem($A.Share, 1032), $WM_SETTEXT, [IntPtr]::Zero, "감사합니다") | Out-Null
[W]::PostMessage([W]::GetDlgItem($A.Share, 1033), 0x00F5, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null
Start-Sleep -Milliseconds 500
"A chat log:`n" + (ChatLog $A)
