"C participants=" + (Participants $C)
"C snapshot (60,20)=" + (DocPixel $C 60 20)

# 회전 (크기 변경)
Cmd $A $ID_ROTATE_RIGHT
Start-Sleep -Milliseconds 800
"after rotate: A=" + (CanvasExtent $A) + " B=" + (CanvasExtent $B) + " C=" + (CanvasExtent $C)
Shot $A 'share_a'
Shot $B 'share_b'

