using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Threading;
public class FakeViewer {
    TcpClient client; NetworkStream stream; Thread reader;
    public List<int> Types = new List<int>();
    public string Reject = "";
    public bool Closed;
    public FakeViewer(string name, int port) {
        client = new TcpClient("127.0.0.1", port);
        stream = client.GetStream();
        var body = new MemoryStream();
        var w = new BinaryWriter(body);
        w.Write((byte)1); w.Write((uint)0x4853504D); w.Write((ushort)1);
        w.Write((uint)name.Length); w.Write(Encoding.Unicode.GetBytes(name));
        var payload = body.ToArray();
        var frame = new byte[4 + payload.Length];
        BitConverter.GetBytes((uint)payload.Length).CopyTo(frame, 0); payload.CopyTo(frame, 4);
        stream.Write(frame, 0, frame.Length);
        reader = new Thread(Read); reader.IsBackground = true; reader.Start();
    }
    byte[] ReadExact(int n) {
        var buf = new byte[n]; int got = 0;
        while (got < n) { int r = stream.Read(buf, got, n - got); if (r <= 0) return null; got += r; }
        return buf;
    }
    void Read() {
        try {
            while (true) {
                var len = ReadExact(4); if (len == null) break;
                var p = ReadExact((int)BitConverter.ToUInt32(len, 0)); if (p == null) break;
                lock (Types) Types.Add(p[0]);
                if (p[0] == 3) { int count = (int)BitConverter.ToUInt32(p, 1); Reject = Encoding.Unicode.GetString(p, 5, count * 2); }
            }
        } catch { }
        Closed = true;
    }
    public string Summary() { lock (Types) return string.Join(",", Types.ToArray()); }
    public void Close() { client.Close(); }
}
'@

