Shot $B 'full_b_rejected'
if ($box -ne [IntPtr]::Zero) { [W]::PostMessage($box, $WM_COMMAND, [IntPtr]1, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 300 }
